/* Integrated public result narratives: <=70-word opening + single-paragraph literature context. */
(function attachResultNarrative(global) {
  "use strict";

  const ROUTES = Object.freeze({
  "special_unusable": {
    "opening": "The response pattern does not provide enough reliable evidence for a judicial portrait. The axis scores can still show individual tendencies, but LAWvalues is withholding the interpretive write-up rather than turning weak or inattentive evidence into a theory of judging.",
    "context": "This is a quality-control result rather than a jurisprudential school. LAWvalues only gives the longer theory explanation when the answers support a stable interpretive pattern. A few isolated scores can still be meaningful, but the deeper write-up depends on relationships among answers: whether the same principle survives across different examples, whether later diagnostic questions confirm rather than undo the earlier pattern, and whether the respondent has given enough information to distinguish a real theory from random or mechanical clicking. Withholding the narrative here is therefore deliberate. It avoids giving the false impression that a person has a coherent view about constitutional meaning, statutory interpretation, precedent, judicial power, or remedies when the response pattern does not justify that claim."
  },
  "special_incoherent": {
    "opening": "Your answers contain several direct conflicts that cannot be explained as ordinary tensions within a judicial philosophy. The individual axis scores still describe real preferences, but forcing them into one coherent account of judging would hide rather than explain what the responses actually say.",
    "context": "This is not the same thing as being eclectic or low-theory. Many serious jurists combine commitments that come from different traditions, and LAWvalues is designed to explain those combinations when the pieces can fit together. This result appears only when the answers produce direct contradictions across more than one jurisprudential domain—for example, affirming and rejecting the same basic source-of-law proposition or switching the governing principle across closely matched legal cases in ways that cannot be reconciled by a normal distinction in the literature. The longer theory paragraph is therefore withheld rather than inventing a school that would make the contradictions disappear. The eight axes remain useful as a map of the separate instincts you expressed, but there is not enough internal consistency to say that those instincts form one defensible jurisprudential position."
  },
  "special_outcome": {
    "opening": "Across several politically mirrored cases, your preferred legal rule changed in the same political direction often enough that LAWvalues cannot confidently treat the pattern as a stable theory of judging. The axis scores remain visible, but a normal jurisprudential portrait would make the answers look more principled than the evidence supports.",
    "context": "LAWvalues normally tolerates a great deal of complexity: a judge can be strict about text but flexible about institutions, deferential in some constitutional settings but aggressive in others, or willing to depart from precedent for one kind of legal reason while preserving it for another. This result is reserved for a different pattern. It appears only when several paired cases hold the legal structure roughly constant while reversing the political valence, and the respondent repeatedly changes the legal principle in the same partisan direction. Because that pattern can imitate almost any jurisprudential label after the fact, the system does not assign a theoretical narrative or thinker match. The point is not that political consequences are never legitimate considerations; many serious theories make consequences, democratic legitimacy, or rights protection legally relevant. The problem is changing the governing principle itself depending on which side benefits."
  },
  "low_theory": {
    "opening": "You do not approach hard cases with a fixed hierarchy telling you that text, history, precedent, purpose, institutional competence, or consequences always comes first. Instead, you let the dispute determine which considerations deserve the most weight. That produces a practical and fact-sensitive style of judging, but it gives fewer rules for predicting the next genuinely difficult case.",
    "context": "The important feature of your jurisprudence is what it does not settle in advance. You have not committed yourself to a master rule saying that text always defeats purpose, history always defeats precedent, or practical consequences matter only after doctrine runs out. That is different from a strong theory of Interpretive Pluralism, which affirmatively argues that several distinct forms of legal reasoning are legitimate parts of a larger method. Your answers are closer to low-theory judging: several kinds of legal reason are available, but the weight they receive depends heavily on the particular dispute. This can make a judge flexible, incremental, and attentive to facts and institutional setting. The tradeoff is that the method supplies less guidance when familiar legal materials point in opposite directions. The result is not incoherent unless the answers actually contradict one another; it is a jurisprudence that is more case-shaped than theory-shaped."
  },
  "opm_mainstream": {
    "opening": "You think constitutional judging begins with law whose meaning was fixed when it was adopted, not with a license to update that law whenever later judges prefer a different answer. You are willing to apply old language to new circumstances, but the governing principle must still come from the enacted Constitution rather than from present-day judicial revision.",
    "context": "You place constitutional authority in the meaning carried by the enacted text at the time of adoption. That is the modern public-meaning form of Originalism. It displaced the older habit of asking primarily what the framers personally intended, because a constitution binds as public law, not as a bundle of private purposes. Founding-era expectations still count as evidence: if nearly everyone applied a clause in one way, that tells us something about what its words conveyed. But the expected application is not itself the rule. A ban on an arbitrary legal caste can keep the same meaning even when later courts confront forms of caste the ratifying generation tolerated or never imagined. So the historical inquiry fixes the legal content, while application can reach new facts without treating the Constitution as having silently changed."
  },
  "opm_construction": {
    "opening": "You think constitutional meaning can be fixed without making every hard case predetermined. Broad provisions can establish a binding principle while still leaving genuine questions unresolved. When that happens, later courts and institutions may need to develop implementing rules inside the space original meaning leaves open, without claiming that the Constitution's meaning itself has changed.",
    "context": "You start with Original Public Meaning: the Constitution's meaning is fixed by the publicly enacted text at adoption. Where you part company with stricter originalists is over how much law that meaning supplies by itself. A broad clause can have a fixed meaning yet still fail to dictate one complete rule for a modern case. New Originalist writers call the first task interpretation—recovering the text's communicative content—and the second construction—building doctrine where that content leaves genuine room. The historical meaning still marks the boundary; construction cannot simply rewrite it. But precedent, institutional practice, legal principle, or other lawful sources may have work to do inside the gap. The real disagreement within Originalism is thus not whether meaning is fixed, but how often fixed meaning leaves judges with a second, legally structured task."
  },
  "opm_methods": {
    "opening": "You treat constitutional adjudication as historical legal interpretation rather than simply historical word-reading. What matters is not only what the words could communicate to an ordinary reader, but also the legal methods and interpretive rules that belonged to the constitutional system when those words became law.",
    "context": "You treat historical interpretation as a legal inquiry, not just a linguistic one. Public-meaning Originalism asks what the constitutional words communicated when adopted; Original Methods adds the question of how a competent legal reader of that period was supposed to interpret such a text. Old rules about technical terms, legal instruments, settled canons, and inherited interpretive practice can affect what the enacted language legally conveyed. That approach can make a provision more determinate than a modern ordinary-language reading would suggest, because some apparent ambiguity was already handled by the legal conventions of the time. The judge is not free to choose whichever historical method produces the preferred result: the method itself has to be recovered as part of the original legal setting. History supplies both the words and, to a significant extent, the tools for reading them."
  },
  "opm_original_law": {
    "opening": "You think the deepest Originalist question is not simply what the Constitution's words meant to readers, but what law the Constitution originally made. That inquiry can include background legal rules, technical meanings, and lawful mechanisms of change, making constitutional judging a reconstruction of an original legal system rather than a purely linguistic exercise.",
    "context": "You aim to recover the law the Constitution originally made, not merely the historical meaning of its sentences. Original-Law theory treats communicative meaning as one part of a larger legal event. The enacted text operated against background doctrines, technical legal categories, rules about legal change, and institutions that already had recognized powers. Those materials can determine legal effect even where ordinary language alone looks open-ended. A modern reader might say a clause leaves a gap; an original-law inquiry may instead find that eighteenth- or nineteenth-century law already supplied the rule for handling it. This shifts Originalism away from historical semantics and toward reconstruction of an original legal system. The payoff is often less room for free-form construction, but not because the text is magically precise: the surrounding law is doing work that a purely linguistic account would miss."
  },
  "opm_intratextual": {
    "opening": "You read the Constitution as a connected legal document rather than a collection of isolated clauses. Historical meaning still controls, but ambiguous language should be understood through recurring words, parallel provisions, structural relationships, and the way the document's parts fit together as a whole.",
    "context": "You read the Constitution as one legal instrument. Public meaning still fixes the historical baseline, but a clause is not interpreted as though it arrived on a separate scrap of paper. Repeated words, parallel structures, neighboring provisions, and the document's architecture can illuminate one another. If the Constitution uses the same term in several places, the pattern may reveal a legal distinction that an isolated dictionary definition would hide; if powers and prohibitions are arranged symmetrically, that structure can constrain how a doubtful clause is read. This is intratextual Originalism: the historical text explains itself partly through its own internal design. It remains different from purposive updating because the inference comes from the enacted Constitution as a whole, not from a later judge's judgment about which arrangement would now work best."
  },
  "opm_correction": {
    "opening": "You think constitutional meaning was fixed at adoption, and you give relatively little weight to precedent once you are convinced that a later court replaced that law with a mistaken rule. Stability matters, but it cannot permanently turn a judicial error into the Constitution itself.",
    "context": "You begin with Original Public Meaning, so precedent sits beneath a constitutional rule whose content was fixed before the precedent existed. That makes stare decisis a doctrine about what judges should do with past decisions, not a mechanism for changing the Constitution itself. When a case is convincingly wrong on the original law, you give correction substantial weight. Reliance, workability, and institutional stability can still counsel against immediate overruling, but age alone does not convert the judicial rule into higher law. This is the restorationist side of the modern Originalist debate: precedent deserves respect because legal continuity matters, yet it cannot permanently displace the source from which the court's authority comes. In practice, the approach is often more willing to reopen entrenched doctrine than settlement-oriented Originalism, especially where the precedent has generated more doctrine than concrete private reliance."
  },
  "opm_settlement": {
    "opening": "You think the Constitution has fixed historical meaning, but you do not treat every departure from that meaning as something courts must immediately erase. Judges inherit an already-developed legal system, so precedent, reliance, and institutional continuity can matter even when fresh historical analysis points elsewhere.",
    "context": "You treat Original Public Meaning as the constitutional benchmark without treating every conflict between history and precedent as an instruction to overrule. The original meaning identifies what the Constitution says; stare decisis addresses a different question—what a court should do after generations of law have grown around a mistaken decision. Reliance, continuity, administrability, and the institutional cost of abrupt doctrinal change can justify leaving some departures in place. The precedent does not become the historical meaning, and the court need not pretend otherwise. Instead, fidelity operates through an inherited legal system in which past judicial settlements have acquired consequences of their own. This is the more precedent-accommodating wing of Originalism: history fixes the standard, but present adjudication can be constrained by the legal world that earlier courts created around it."
  },
  "opm_higher_law": {
    "opening": "You think objective moral principles help explain why law can have authority, but you also think law exists to settle questions judges could otherwise keep reopening. That makes historically fixed constitutional law compatible with Natural Law: moral reasoning helps explain why legitimate positive law binds rather than giving judges a standing license to replace it.",
    "context": "You combine Originalism with a classical Natural-Law account of positive law. The two operate at different levels. Natural law supplies reasons about legitimate authority and the common good; positive law resolves the many questions on which sound moral reasoning permits more than one acceptable arrangement. A constitution can therefore bind precisely because it settles matters that judges should not reopen whenever they see a morally preferable option. Originalism identifies the content of that settlement by looking to the Constitution's fixed historical meaning. Morality still supplies outer limits and helps explain why legal authority deserves obedience, but it does not erase the difference between what is morally best and what has actually been made law. The combination produces a higher-law theory that is often more respectful of enacted legal settlement than the phrase 'natural law' suggests."
  },
  "oi_mainstream": {
    "opening": "You think constitutional interpretation should recover the intentions behind the Constitution, not merely the public meaning later readers can extract from the enacted words. The enacting generation's purpose is therefore part of what gives the constitutional rule its content, making authorial intention legally central rather than merely historical evidence.",
    "context": "You make the enacting generation's intention part of the constitutional rule itself. Original Intent asks what the constitution-makers meant to communicate or accomplish through the provision, rather than treating the public meaning of the enacted words as independently decisive. That does not require collecting every private hope voiced at the convention. A workable intentionalist theory has to identify an institutional or collective intention from public acts, drafting choices, debates, and the structure of the enactment. The hard cases arise when that reconstructed intention and the best public reading diverge. Public-meaning originalists say the law is what was publicly enacted even if some framers privately expected something else; you give the enactors' intended legal decision greater authority. History is doing more than supplying linguistic context—it identifies the lawmaking choice the text was meant to put into effect."
  },
  "oi_semantic": {
    "opening": "You treat original intent as a theory of meaning, not merely as a device for restraining judges. On your view, interpreting a constitutional text means recovering what its authors intended to communicate, so intent can control because it is part of what the enacted language meant.",
    "context": "You defend Original Intent as a theory of meaning rather than merely as a restraint on judges. On this view, legal language is a communicative act, and communication cannot be understood without some account of what the lawmaking authors intended to convey. Public meaning remains relevant because authors normally communicate through shared language, but it is evidence of the intended communication rather than the ultimate object of interpretation. That separates your position from older arguments that appealed to intent mainly because it kept courts politically modest. The dispute with Public Meaning is more basic: what makes the enacted words mean what they mean? Your answer is that the relevant lawmaking intention helps constitute their meaning. The difficult part is collective authorship—showing how a legislature or ratifying public can have an intention precise enough to guide adjudication without collapsing into selective quotations from individual speakers."
  },
  "oi_construction": {
    "opening": "You think founding intent fixes constitutional meaning, but you also think that intent can leave genuine legal questions unresolved. When the intended meaning runs out, later constitutional doctrine may legitimately develop within the space the original settlement left open rather than pretending the founders supplied a complete rule for every case.",
    "context": "You combine an intentionalist account of constitutional meaning with a separate account of doctrinal development. The enacting intention fixes what the constitutional provision means, but that intended meaning need not contain a ready-made rule for every future dispute. Where the historical settlement genuinely leaves room, later courts and institutions may construct implementing doctrine without claiming that the original intention has changed. This keeps one foot in Original Intent and another in the interpretation/construction framework more often associated with New Originalism. The fixed intention still excludes some outcomes; it simply does not decide everything within those limits. The next question is institutional rather than semantic: which sources—precedent, practice, principle, democratic choice—may legitimately fill the space. Your view is historical about constitutional meaning but not about every doctrinal detail built on top of it."
  },
  "originalist_generic": {
    "opening": "You think present constitutional judging is constrained by law fixed at adoption, even though your answers do not cleanly resolve which Originalist account best identifies that law. History is therefore authoritative for you, but the precise theory connecting historical meaning to modern cases remains comparatively open.",
    "context": "You are clearly on the fixed-law side of constitutional theory: adoption settles something that later judges are not free to revise simply because contemporary values have changed. What remains unresolved is exactly what historical object carries that authority. Modern Originalists divide over public meaning, enacting intention, historically accepted interpretive methods, and the broader body of law the Constitution originally made. Those choices can produce different answers about ambiguity, precedent, and the amount of room left for later doctrine. The common ground is narrower but still substantial. History supplies a legal constraint, not merely background information, and constitutional change cannot be justified simply by announcing that present circumstances call for a better rule. Your answers establish that fixed-law commitment more firmly than they establish one particular Originalist school."
  },
  "living_mainstream": {
    "opening": "You do not think present constitutional law is exhausted by the meaning fixed at adoption. Later precedent, experience, changed circumstances, and contemporary understandings can legitimately shape what constitutional commitments require, so the judge's task includes legal development rather than only historical recovery.",
    "context": "You treat constitutional law as capable of lawful development after adoption. The text and its history still anchor the system, but they do not exhaust the legal content a court may recognize centuries later. Precedent, institutional practice, changed factual conditions, and settled understandings can alter what constitutional commitments require without a formal amendment. The difficult question is not whether judges may 'update values' at will; serious living theories disagree sharply about the mechanism of change. Some rely on common-law precedent, some on political contestation, some on tradition, and some on broader constitutional principle. Your answers support the general developmental claim without fastening it to one narrower mechanism. Compared with Originalism, the difference is legal rather than merely practical: post-adoption developments can become part of the law courts are entitled to apply, not just evidence about an unchanged historical meaning."
  },
  "living_democratic": {
    "opening": "You think constitutional law develops through interaction among courts, political movements, officials, and public argument rather than through judges alone or through a meaning frozen at adoption. Courts still enforce rights, but democratic constitutional debate can legitimately help shape the understandings those courts eventually apply.",
    "context": "You treat constitutional development as a public process in which courts are important participants but not sole authors. Democratic Constitutionalism gives sustained political argument, social movements, elections, legislation, and institutional conflict a role in shaping the constitutional understandings that courts eventually enforce. Judicial review remains part of the system; the theory is not simple majoritarianism. Courts can protect rights against present political majorities while still recognizing that the meaning and social authority of those rights have been formed through democratic contestation outside the courthouse. This places your theory between two cleaner models: Originalism, which fixes constitutional content at adoption, and court-centered Living Constitutionalism, which locates most lawful development in doctrine. Here constitutional law is partly made through an ongoing relationship between legal institutions and a politically engaged public."
  },
  "living_transformative": {
    "opening": "You think constitutional interpretation can be part of an ongoing legal project of changing inherited institutions, not merely preserving them while adapting at the edges. Courts should read constitutional commitments with an eye toward the social and political transformation those commitments require.",
    "context": "You read constitutional law as an ongoing project of institutional change. Transformative Constitutionalism is most at home where a constitution was adopted against an inherited order marked by hierarchy, exclusion, or authoritarianism. Broad guarantees of equality, dignity, participation, or democracy are then read not merely as limits on isolated government acts but as commitments to alter the structures that reproduced the old order. Courts can play an active role in that project, although they remain constrained by text, institutional competence, and democratic legitimacy. This is more purposive than ordinary precedent-driven Living Constitutionalism: development is measured against the constitution's transformative commitments, not only against the path of past cases. The risk is correspondingly larger—an ambitious theory of constitutional purpose can give judges substantial room to decide what transformation requires."
  },
  "living_moments": {
    "opening": "You think formal amendment is not the only way a constitutional order can undergo legitimate higher-law change. In extraordinary periods of sustained popular mobilization and repeated institutional ratification, political action can sometimes produce a new constitutional settlement that later courts should recognize.",
    "context": "You allow constitutional change outside Article V, but only through politics that looks very different from ordinary legislation. Constitutional-moments theory asks whether a movement achieved sustained popular mobilization, repeated electoral endorsement, and institutional ratification strong enough to count as higher-law politics. A single election or temporary majority is not enough. The theory was built to explain major shifts in American constitutional practice that seem too large to describe as ordinary precedent yet were never formally added to the text. Courts later treat those settlements as part of the constitutional order because the political system itself went through an extraordinary process of constitutional change. This makes your Living Constitutionalism democratic but demanding: informal change is possible, though it requires something closer to a constitutional founding episode than to routine policy victory."
  },
  "common_law_mainstream": {
    "opening": "You think constitutional law grows through precedent, practice, and accumulated institutional experience. Past decisions do more than imperfectly report an unchanged Constitution; over time they can become part of the legal structure that later judges inherit and develop.",
    "context": "You treat constitutional law much as a common-law judge treats an old line of cases: as an inherited body of rules and principles that can be extended, narrowed, distinguished, or occasionally abandoned through later adjudication. The constitutional text begins the inquiry, but once a dense body of doctrine has accumulated, precedent can carry more practical legal weight than a fresh reading of the founding-era words. David Strauss's version of the view is explicit about this: constitutional provisions themselves can recede as later decisions give them shape. Change is usually incremental because each court works with what earlier courts have already built, and stare decisis is part of the method rather than an afterthought. The attraction is continuity without historical freezing; the cost is that much of constitutional law may rest on judicially developed doctrine whose authority comes from acceptance and repetition rather than from a single textual command."
  },
  "common_law_tradition": {
    "opening": "You think constitutional liberty develops through precedent and historically embedded tradition rather than through either fixed founding expectations or free-standing modern moral judgment. Change is legitimate, but it should grow out of the accumulated experience of the legal order.",
    "context": "Your constitutionalism develops through precedent, but not through precedent alone. Longstanding practices and the broader tradition of ordered liberty help define the path on which doctrine may move. A claimed right gains force when it fits a historical pattern of protected freedom; novelty counts against it unless the broader tradition supports the extension. This differs from Originalism because later legal experience can change constitutional doctrine, and it differs from contemporary moral updating because the court does not begin with a free-standing judgment about which liberties deserve protection now. Tradition supplies both continuity and constraint. The approach can support genuine change—common-law reasoning works by analogy and extension—but it asks new claims to grow out of an inherited legal culture rather than displace it wholesale."
  },
  "common_law_strong_rights": {
    "opening": "You think some fundamental legal rights can be rooted so deeply in the constitutional common-law tradition that ordinary legislation cannot simply erase them, even when no written higher-law clause expressly supplies the limit. Judicially articulated principle can therefore constrain legislative supremacy.",
    "context": "You give the common-law tradition a higher-law role. Ordinary Common-Law Constitutionalism lets precedent and practice develop constitutional doctrine around an accepted written constitution; your position goes further by allowing some fundamental common-law rights or principles of legality to constrain legislation even without an express written clause doing the work. The argument is familiar in systems with traditions of parliamentary sovereignty: certain judicially articulated principles—access to courts, legality, basic rights—may be too fundamental to treat as ordinary rules that a legislature can casually erase. That places substantial responsibility on judges to distinguish genuine constitutional fundamentals from ordinary judge-made doctrine. It also shifts the basis of review away from a single enacted text and toward the constitutional character of the legal tradition itself. The result is common-law judging with a real, and controversial, claim to higher-law authority."
  },
  "common_law_source_bound": {
    "opening": "You think law gets its authority from recognized legal institutions, yet those institutions can change constitutional law over time through precedent and practice. Constitutional development is legitimate because it occurs through law's own sources, not because judges have a free-standing power to update constitutional values.",
    "context": "You combine two claims that are often treated as opposites: law is source-based, and constitutional law can change without formal amendment. They fit together if precedent and official practice are themselves recognized sources. A Positivist need not freeze the Constitution at adoption; the source thesis only says that legal content depends on the practices and institutions the legal system treats as authoritative. Common-Law Constitutionalism supplies the developmental mechanism. Repeated decisions, settled doctrine, and accepted governmental practice can acquire legal status and become part of what later courts inherit. David Strauss's account is especially clear that, after enough doctrine accumulates, the operative constitutional law may be found more in precedent than in a fresh reading of the text. Your view permits genuine legal change while keeping that change tied to identifiable institutional sources rather than to free-standing judicial moral judgment."
  },
  "common_good": {
    "opening": "You think public law should be understood through a classical idea of legitimate authority directed toward the common good. Individual autonomy and historically fixed meaning matter, but neither exhausts the legal purpose of government or the principles that should guide interpretation.",
    "context": "You read public law through a classical account of political authority. Government exists to secure conditions of common life that individuals cannot supply alone, so constitutional interpretation cannot be reduced either to maximizing private autonomy or to recovering historical linguistic meaning. Positive law still has an important settlement function: institutions may choose among several reasonable arrangements and bind the community through that choice. But broad grants of authority and open-textured legal standards are read in light of the purposes of legitimate government, including public welfare, justice, peace, and social order. This gives judges and administrators more room to reason from public ends than mainstream Originalism or hard Textualism would allow. It also demands a substantive account of the common good, which is exactly where the modern controversy lies: the theory constrains private and public power through objective purposes, but those purposes themselves require judgment."
  },
  "positivist_mainstream": {
    "opening": "You think the existence of law ultimately depends on recognized legal sources and social practices, not on whether the resulting rule is morally good. A cruel or foolish rule can still be law, even though judges and citizens may have powerful moral reasons to condemn or change it.",
    "context": "Your theory is Legal Positivism in its modern sense. The central claim is not that morality is unimportant, or that judges should approve unjust laws. It is that the question 'what law exists?' is ultimately answered by social and institutional facts: enactment, precedent, official practice, and the rules a legal system recognizes as authoritative. Moral criticism is a different question. That separation matters because it allows a judge to say both that a rule is legally valid and that it is gravely unjust. Modern Positivism also accepts that legal systems can contain broad language, hard cases, and discretionary judgment; source-based legality does not imply mechanical judging. Your answers do not require one of the more specialized Positivist theories about sovereign commands, hierarchies of norms, or social planning. They fit the mainstream idea that law is a human institutional practice whose validity depends on how the legal system identifies authoritative sources, not on whether those sources reach morally correct results."
  },
  "positivist_inclusive": {
    "opening": "You think law is ultimately grounded in social rules and institutions, but those rules can themselves tell courts to apply genuine moral standards. Morality can therefore become part of legal validity without ceasing to be incorporated through a source-based legal system.",
    "context": "Your Positivism is inclusive. All Positivists begin from the idea that law depends on social or institutional facts rather than on moral merit automatically making a norm law. The inclusive branch adds an important qualification: the socially recognized rules of a legal system can themselves make moral criteria legally relevant. A constitution might, for example, forbid 'cruel' punishment or protect 'equal' treatment in language that requires moral judgment. On your view, morality matters there because the legal system has incorporated the moral standard into its own law. Exclusive Positivists resist that conclusion, arguing that legal validity must remain identifiable from source facts without moral merit itself becoming the test. Your answer therefore occupies a real internal dispute about how source-based law can use moral concepts. It preserves the Positivist claim that law is grounded in social practice while allowing those practices to direct courts toward genuine moral reasoning as part of determining what the law requires."
  },
  "positivist_exclusive": {
    "opening": "You think legal validity must remain identifiable from social and institutional sources without making moral correctness itself the test of what law exists. Morality may guide criticism or political reform, but it should not become an independent criterion for identifying valid law.",
    "context": "Your Positivism is on the exclusive side of a major internal debate. Inclusive Positivists agree that law is grounded in social sources but think those sources can incorporate genuine moral criteria into the test for legal validity. Exclusive Positivists draw a harder line. For law to function as an authority, its requirements must be identifiable through the social sources that created or recognized them rather than by asking the interpreter to revisit the same moral reasons the law was supposed to settle. That does not make moral language meaningless or forbid judges from applying evaluative legal standards. The claim is narrower: moral merit itself cannot be the ultimate fact that makes a norm legally valid. Your result therefore treats the source/merit distinction as especially important. A law can be wicked, foolish, or unjust and still be law; the moral defect supplies a reason to criticize, disobey, or change it, not automatically a reason to deny that the legal system created it."
  },
  "positivist_normative": {
    "opening": "You do more than describe law as source-based; you think source-following is itself an important institutional discipline. Even when judges can imagine morally better answers, legal systems work better when contested moral lawmaking is left mainly to politically accountable institutions.",
    "context": "Your view is often called Normative or Ethical Positivism. Ordinary Legal Positivism is mainly a claim about what makes law valid: social sources and institutional practices rather than moral merit. Your answers add a further argument about how judges should behave. Source-based legality is valuable because it makes law more predictable, keeps judges from turning contested moral judgments into legal rules, and leaves major changes to institutions with stronger democratic credentials. This does not mean courts never exercise judgment or that moral reasoning is irrelevant to law. It means that when recognized legal sources settle the question, judges should usually treat that settlement as a feature rather than a defect. Your theory therefore turns the source thesis into an institutional principle of restraint. The legal system gains legitimacy partly by distinguishing the law that has actually been adopted from the moral or political rule a judge might personally prefer to adopt."
  },
  "natural_law_mainstream": {
    "opening": "You think objective moral principles matter to law, but you do not treat morality as a standing permission for judges to replace positive law. One of law's important jobs is to settle questions that practical morality leaves open and give a community a determinate rule.",
    "context": "Your answers fit the settlement-oriented core of modern Natural Law. The theory rejects the idea that legal validity and moral reason can be completely separated, but it is often misunderstood as saying that judges may ignore any law they regard as unjust. A more serious Natural-Law account gives positive law a central role. Moral principles set important limits and purposes, yet they frequently leave several reasonable ways of organizing social life open. Legislatures, constitutions, and other legitimate institutions then make a determination: they choose among those possibilities and create a rule that can bind because coordination and settled authority themselves serve the common good. That makes positive law more, not less, important. The hardest questions arise at the boundary—when moral defect is so severe that ordinary settlement loses its authority, or when broad legal language itself asks judges to reason morally. Your result stays closer to the mainstream settlement view than to a theory of free judicial moral correction."
  },
  "natural_law_strong": {
    "opening": "You think moral defect can sometimes reach beyond making a rule unjust and undermine its status as law itself. Positive law normally settles questions and deserves authority, but sufficiently serious violations of objective moral requirements can defeat that legal claim.",
    "context": "Your Natural-Law position is stronger than the settlement-oriented mainstream. Many modern Natural Lawyers emphasize that positive law can remain legally valid even when it is seriously unjust, because law serves coordination and settlement functions that morality alone cannot perform. Your answers preserve that background but add a limit: some normative defects are grave enough that the purported rule fails as law rather than merely becoming bad law. The difficulty is drawing that line. If every injustice destroyed legal validity, ordinary legal disagreement would collapse into moral disagreement and judges would gain enormous power to disregard enacted rules. A strong Natural-Law theory therefore needs a demanding account of when injustice becomes legally disqualifying. Your result places real weight on objective morality as a condition of legality while still distinguishing that exceptional failure from the ordinary case in which positive law settles among several imperfect but legally valid choices."
  },
  "interpretivist": {
    "opening": "You think legal practice contains principles as well as enacted rules, and those principles can supply real legal answers in hard cases. Judges should interpret the existing legal system in the way that best fits its history while giving its institutions and rights the strongest coherent justification.",
    "context": "Your theory is Interpretivist rather than simply 'moral' or 'non-Positivist.' The distinctive claim is that legal rights emerge from an interpretation of institutional practice. Statutes, precedents, and constitutional decisions matter, but their legal significance is understood through the principles that best fit that history and justify it as a coherent scheme of political rights and responsibilities. That is different from a Positivist account in which recognized sources determine the law until the sources run out, leaving judges with discretion to make new law. On your view, principles already embedded in the practice can continue to supply legal answers even when no explicit rule settles the case. It is also different from giving judges a free-standing power to impose whichever moral theory they like: the justification must fit the actual legal history. Your result therefore treats hard-case reasoning as constructive interpretation—moral in part, but constrained by the institutional record it is trying to make sense of."
  },
  "nonpos_moral_impact": {
    "opening": "You think legislatures and courts make law by changing people's actual moral rights and obligations. The legal institutions matter because of the moral impact their actions produce, not because they create a separate source-based category of obligation alongside morality.",
    "context": "Your Non-Positivism follows Moral Impact Theory. The central move is to reject the idea that law consists of one set of source-generated obligations while morality supplies a separate set of reasons for evaluating them. On this view, legal institutions act in the real moral world: statutes, judgments, and official decisions change what people owe one another, and the resulting moral rights and obligations are the law. That differs from traditional Natural Law, which often begins with objective practical principles and asks how positive law determines or participates in them. It also differs from Interpretivism, which identifies legal rights through the principles that best fit and justify institutional practice. Moral Impact Theory focuses instead on the moral consequences of the institutions' actions themselves. Your answer therefore treats legal sources as causally crucial without treating source pedigree as sufficient: what ultimately matters is the normative change the legal system has actually brought about."
  },
  "nonpos_moral_practice": {
    "opening": "You think a person who claims a legal right is ultimately claiming a genuine moral right, not invoking a separate kind of obligation that exists only because legal sources created it. Legal practice is one part of our broader moral practice rather than a separate normative world.",
    "context": "Your Non-Positivism takes a one-system view of law and morality. Instead of treating 'legal rights' as a distinct source-generated category that can be identified first and morally assessed later, you understand courtroom claims as claims about people's real moral rights and responsibilities. Legal institutions, precedents, and statutes remain enormously important because they affect those rights and structure the social practices through which they are understood. But they do not create an entirely separate normative domain called law. This differs from Moral Impact Theory, which emphasizes how institutional action changes the moral situation and thereby makes law. Your result is more directly about the kind of claim legal argument makes: when a court says someone has a legal right, it is ultimately saying that the person truly has that right in the relevant moral practice. The theory therefore rejects the conceptual separation between legal normativity and moral normativity at a very deep level."
  },
  "nonpos_extreme": {
    "opening": "You think ordinary injustice can coexist with legal validity, but there is a point at which injustice becomes so extreme that a purported rule loses its claim to be law. Your view therefore rejects both simple source-only validity and the idea that every moral defect destroys legality.",
    "context": "Your position is a narrow form of Non-Positivism built around extreme injustice. It accepts much of the practical attraction of source-based law: wicked, foolish, and unfair enactments can still be legally valid, and judges cannot treat ordinary moral disagreement as permission to ignore positive law. But the connection between law and morality is not unlimited. At some point, a norm's injustice can become so radical that calling it 'law' would contradict the legal order's own claim to govern through right rather than sheer power. This is a deliberately exceptional doctrine. Its point is not to make legal validity depend on a judge's general moral evaluation, but to preserve a threshold beyond which positive pedigree cannot carry the whole concept of law. The difficult theoretical question is where that threshold lies and how a court can identify it without turning an emergency principle into routine moral review. Your answers take that exceptional moral limit seriously."
  },
  "fullerian": {
    "opening": "You think law can fail not only because of what it commands, but because of how it is made and administered. Secret, retroactive, contradictory, impossible, or systematically ignored rules can fail the basic conditions that make governance through law possible.",
    "context": "Your theory focuses on the internal morality of legality. The central idea is that law is a distinctive way of governing people through rules, and that enterprise has structural requirements of its own. Rules must be reasonably public, prospective, understandable, consistent, possible to obey, sufficiently stable, and administered in a way that matches what officials announced. These are not merely optional virtues of a well-run legal system. On the Fullerian view, sufficiently serious failure can undermine the system's claim to be governing through law at all. That makes the theory different from ordinary Natural Law, which usually asks more directly about the moral purposes or substantive justice of law, and different from Positivism, which can treat legality's procedural virtues as important without making them conditions of legal status. Your result therefore finds a law-morality connection in the form and practice of legal governance itself."
  },
  "textualist_mainstream": {
    "opening": "You think judges should enforce the meaning of the law Congress actually enacted rather than reshape it around an unenacted purpose. That does not mean reading words in isolation: grammar, ordinary usage, surrounding provisions, and legal context are all part of working out what the enacted text means.",
    "context": "Your statutory method is modern Textualism. The important point is that contemporary Textualism is not literalism. A textualist does not normally ask whether one dictionary definition can be made to fit an isolated phrase and then stop. The inquiry uses grammar, ordinary linguistic usage, the structure of the statute, surrounding provisions, and relevant legal conventions to determine what the enacted words communicate in context. The real divide with Purposivism concerns what happens when the text and the law's broader apparent purpose pull apart. Your approach treats the enacted language as the controlling legal object. Purpose can help explain context, but it cannot simply authorize a judge to repair a compromise, omission, or awkward rule that Congress actually enacted. That gives democratic lawmaking a particular form of respect: the court enforces the legal bargain that survived the legislative process rather than the cleaner policy that a judge thinks Congress probably should have written."
  },
  "textualist_institutional": {
    "opening": "You think judges are constrained by enacted law, but faithful interpretation happens inside an institutional system rather than a linguistic vacuum. Text and statutory context come first, while precedent, delegated responsibility, expertise, and administrability can matter to who should resolve genuine uncertainty.",
    "context": "The important Textualist dispute for you begins after modern Textualism has already rejected literalism. Grammar, ordinary usage, statutory structure, and legal context all help determine what Congress enacted. The harder question is what happens when those materials still support more than one serious reading. A court-centered textualist treats selecting the best legal reading as irreducibly judicial: agencies may know more about the subject, but determining the law's limits belongs to courts. You are more institutionalist. The enacted text remains the constraint, yet Congress's allocation of administrative responsibility, stable precedent, expertise, and the practical structure of the statutory program can matter to who resolves the remaining uncertainty. That does not give an agency permission to substitute a better policy for the statute. It means textual fidelity operates inside a legal system that assigns different institutions different responsibilities. Institutional competence therefore becomes part of the interpretive picture rather than an excuse to abandon the text."
  },
  "textualist_bargain": {
    "opening": "You think the hardest part of judging is accepting that enacted law may be awkward, incomplete, or badly designed without giving courts permission to repair it. Omissions, exceptions, and compromises can be part of the legal bargain itself, not defects to be smoothed away in the name of coherence.",
    "context": "Your Textualism sits on the harder enacted-bargain side of the modern movement. Contemporary textualists generally agree that context matters: statutes are read as whole legal instruments, not as isolated dictionary entries. The dispute is how far contextual coherence may go. A more holistic textualist may use the structure of the statute and ordinary legal sense to choose the best reading among several plausible options. Your answers give greater weight to the possibility that awkwardness is deliberate or at least legally consequential. Legislation is produced through bargaining, compromise, exceptions, and omissions; the enacted words may reflect a deal that no single policymaker would have designed alone. A judge who 'fixes' the statute to better serve its general purpose can therefore erase part of the bargain that made the law possible. Your theory treats that imperfection as one of the central disciplines of statutory interpretation: courts apply what became law, not the cleaner statute they wish Congress had enacted."
  },
  "textualist_categorical": {
    "opening": "You combine text-centered interpretation with a strong preference for categorical legal rules. When constitutional or statutory language states a right or boundary in rule-like terms, you resist converting it into a balancing test simply because the government has important competing interests.",
    "context": "Your Textualism is unusually categorical in doctrinal form. Modern textualists agree that enacted language constrains interpretation, but they do not all agree that the law should be implemented through bright-line rules. Open-ended rights can be applied through standards, balancing, or proportionality even by judges who are strict about the source and meaning of the legal text. Your answers push the other way. Once the text establishes a categorical right or boundary, you are reluctant to let courts weaken it by reweighing the government's interests case by case. The attraction is partly institutional: clear rules constrain judges as well as government officials, reducing the risk that the strength of a right will depend on who is doing the balancing. That can make your judging simultaneously text-bound and strongly rights-enforcing. The court may invalidate popular laws aggressively, not because it has broad moral discretion, but because it thinks the enacted legal category leaves comparatively little room for discretionary adjustment."
  },
  "intentionalist_mainstream": {
    "opening": "You think statutory interpretation should recover what the legislature meant to accomplish through the law it enacted. Text remains important evidence and constraint, but the interpretive target is the lawmaking body's intended legal decision rather than wording or objective purpose considered entirely apart from that intention.",
    "context": "Your statutory theory is Intentionalist. The central disagreement with Textualism concerns the object of interpretation. A textualist asks what the enacted language means in its legal and linguistic context, even if reliable historical evidence shows that some lawmakers privately expected something else. You give genuine legislative intention a more direct legal role. That does not reduce the task to reading isolated statements by individual legislators; serious Intentionalism has to explain how a multi-member institution can form a lawmaking intention and how courts can identify that intention without cherry-picking convenient history. It also differs from Purposivism. A statute can have an objective purpose that is broader or cleaner than what the lawmakers actually intended to enact. Your view treats the intended legal choice as the relevant target. The theory therefore takes legislative agency seriously: Congress is not merely a machine that produces text, but an institution capable of acting for reasons and intending the legal change its enactment is meant to make."
  },
  "intentionalist_imaginative": {
    "opening": "You think legislative intent matters even when lawmakers never considered the exact problem before the court. In those cases, the judge should reconstruct what the legislature would have intended had it confronted the issue, using the enacted scheme and the lawmakers' evident purposes as guides.",
    "context": "Your Intentionalism uses imaginative reconstruction. Ordinary historical intent asks what the legislature actually meant or decided when it enacted the law. Hard cases often arise precisely because the lawmakers never confronted the new technology, unusual fact pattern, or loophole now before the court. Your theory does not treat that silence as the end of the inquiry. Instead, the judge asks a counterfactual question: what would this legislature, pursuing the commitments reflected in the enacted statute, have intended if the unforeseen problem had been presented to it? That makes your approach more openly constructive than theories of actual group intention. It also creates a familiar danger: the more hypothetical the reconstruction becomes, the easier it is for a judge's own policy preferences to masquerade as legislative intent. The discipline therefore has to come from the enacted statute, the historical legislative project, and evidence of how the lawmaking body actually made choices—not simply from what the judge now regards as sensible."
  },
  "intentionalist_congress": {
    "opening": "You think statutory interpretation should take Congress seriously as an institution that communicates through more than the final sentence-level text. When language is genuinely ambiguous, reliable committee materials and the actual legislative process can be legitimate evidence of the legal meaning Congress intended to enact.",
    "context": "Your Intentionalism is institutionally Congress-aware. The important disagreement is not whether enacted text matters—it does—but what counts as reliable evidence of the lawmaking body's intended legal choice when the text is genuinely unclear. Hard Textualism is suspicious of legislative history because committee reports, sponsor statements, and similar materials did not pass through the constitutional lawmaking process and can be selective or manipulable. Your answers give those materials a legitimate, though not unlimited, role. Congress has procedures through which committees investigate, draft, explain, negotiate, and communicate legislation; courts interpreting ambiguous statutes can learn from the materials that participants themselves rely on in that process. This is not a claim that any floor speech can override clear text. It is an argument that interpretation should reflect how Congress actually legislates rather than an abstract model in which the enacted words arrive without an institutional history. Your result therefore joins Intentionalism to a Legal-Process concern with the real practices of the lawmaking institution."
  },
  "purposivist_mainstream": {
    "opening": "You think statutes should be read as legal projects with purposes, not merely as strings of words. Text remains important, but when rigid wording and the law's evident objective pull apart, judges may need to interpret the rule in a way that makes the statutory scheme work as the legislature designed it to work.",
    "context": "Your statutory theory is Purposivist. The key distinction is between the meaning of enacted language and the objective purpose of the legal scheme. A textualist treats the enacted linguistic meaning as controlling even when the result frustrates a broader policy that seems to have motivated the statute. A purposivist gives the statute's objective more independent interpretive force. That does not mean ignoring the text or searching for lawmakers' private intentions. Purpose is normally inferred from the statute as a whole, the problem it addresses, and the legal structure it creates. The difficult cases are those where the apparent purpose and the most natural reading of the enacted words diverge. Your answers are more willing than Textualism to let the law's project shape the legal effect, especially to avoid interpretations that make the scheme self-defeating or easy to evade. The theory's central challenge is preserving that purposive coherence without turning interpretation into a general judicial power to improve imperfect legislation."
  },
  "purposivist_proportional": {
    "opening": "You combine purpose-centered interpretation with a structured way of resolving rights conflicts. A law's objective matters, but government must also show that burdens on rights genuinely serve that objective, are no broader than necessary, and remain justified in light of the harm imposed.",
    "context": "Your jurisprudence links Purposivism to Proportionality. Purposivism asks what legal objective a statute or constitutional rule is trying to serve and reads the legal materials in light of that objective. Proportionality then supplies a structured method for deciding whether government may pursue that purpose at the expense of a right. The inquiry is more disciplined than saying that judges may simply 'balance' whatever interests seem important: the government needs a legitimate goal, a measure genuinely connected to that goal, no less restrictive workable alternative, and a burden on the right that remains justified by the public benefit. The two theories reinforce each other because both take legal purpose seriously, but they answer different questions. Purpose helps identify what the law is trying to do; proportionality tests whether the means chosen to do it are legally justified. Your result therefore favors explicit, reason-giving judicial judgment over categorical rules that settle rights disputes without examining fit and necessity."
  },
  "legal_process_mainstream": {
    "opening": "You think hard cases cannot be understood by asking only which interpretation seems best. Courts should also ask who was assigned the decision, which institution is competent to make it, what has already been settled, and what kind of reasoned explanation the legal system requires.",
    "context": "Your theory is Legal Process. It shares Purposivism's interest in the purposes of legal rules but adds a deeper account of institutional role. The legal system is a division of labor among legislatures, agencies, courts, executives, and other institutions. A good answer therefore depends not only on the substantive merits but on which institution was authorized to decide, what procedures it used, what expertise it has, and what earlier settlements deserve respect. This is the idea behind questions such as 'whose job is this?' and 'what kind of reason is this institution entitled to give?' Legal Process does not require courts to be passive. Courts can insist on reasoned decisionmaking, enforce institutional boundaries, and develop doctrine where their role calls for it. But the theory resists treating judges as universal problem-solvers. Your result therefore understands legal reasoning as institutionally situated: purpose, precedent, and practical judgment matter through the structure of authority that the legal system has created."
  },
  "legal_process_agency": {
    "opening": "You think agencies can engage in genuine legal interpretation rather than acting only as policy bodies waiting for courts to supply the law. Their expertise, internal legal norms, reason-giving duties, and responsibility for administering a statutory program can make agency interpretation part of the legal process itself.",
    "context": "Your Legal Process theory is unusually administrative. The central claim is that an agency charged with carrying out a statute can itself be a legal institution, not merely a policymaker whose work begins where legal interpretation ends. Agencies develop expertise, internal norms, precedents, procedures, and reason-giving practices while bearing continuing responsibility for making a legislative program function. That can give their statutory interpretation a form of legal authority or respect even when courts retain the ultimate power to police legal boundaries. This differs from a court-centered view in which determining statutory meaning is inherently judicial and agency expertise matters only to factual or policy questions. Your answers instead treat institutional competence as part of the legal question: Congress can allocate interpretive responsibility as well as administrative tasks. The theory still requires supervision and lawful limits; agency autonomy is not immunity from judicial review. But faithful statutory governance can involve multiple legal institutions rather than one court announcing the meaning for everyone else."
  },
  "legal_process_neutral": {
    "opening": "You think constitutional decisions should rest on principles a court is prepared to apply beyond the immediate parties and political stakes. A result-specific reason is not enough; judicial legitimacy depends on offering a rule that can be generalized across materially similar cases.",
    "context": "Your Legal Process theory puts unusual weight on neutral principles. The idea is not that judges can become politically or morally neutral in some absolute sense. It is that constitutional adjudication should be justified by principles capable of extending beyond the case whose outcome the judge currently favors. A court must be willing to apply the same rationale when the identities, parties, or political consequences are reversed. That requirement disciplines judicial review in two ways. It forces judges to articulate reasons at a level of generality that can guide later cases, and it makes outcome-specific manipulation easier to expose. Neutral-principles reasoning fits the broader Legal Process concern with reasoned elaboration: courts earn authority by explaining decisions through legal principles appropriate to the judicial role rather than by announcing desirable results. Your result therefore treats consistency across cases as part of the legitimacy of constitutional judgment, not merely as a convenient virtue of precedent."
  },
  "pragmatist_mainstream": {
    "opening": "You think hard cases sometimes leave judges with a real choice rather than a hidden answer waiting to be discovered. When that happens, consequences, administrability, incentives, and institutional performance can be legitimate reasons for choosing among legally defensible options.",
    "context": "Your theory is Pragmatist because practical consequences do more than help reveal the meaning or purpose of another legal source. They can become independent reasons for decision once the ordinary legal materials leave genuine room. That separates Pragmatism from Purposivism, where consequences usually matter because they illuminate or advance the statute's objective, and from Textualism, where undesirable consequences cannot ordinarily override enacted meaning. A Pragmatist judge asks what rule will work, how institutions will administer it, what incentives it creates, and whether inherited doctrine is producing avoidable dysfunction. The method does not necessarily reject precedent or rules; those can have great practical value because they promote predictability and coordination. But their authority is less absolute. Your answers place workability and consequences nearer the surface of legal reasoning rather than forcing them to hide behind doctrinal language. The tradeoff is that Pragmatism supplies fewer fixed instructions about how competing consequences should be ranked in advance."
  },
  "pragmatist_obsolescence": {
    "opening": "You think an old statute can become so badly mismatched with the later legal order that courts should not mechanically extend it forever. In an extreme case, judicial doctrine can force contemporary political institutions to take a fresh look rather than letting obsolete law govern by inertia.",
    "context": "Your Pragmatism is unusually willing to confront statutory obsolescence. Ordinary Textualism says that a valid statute remains law until the legislature changes it, even if later legal developments make the old rule awkward. A more conventional Pragmatist may interpret flexibly at the margins but still accept that basic democratic allocation. Your answers go further. When an old statute becomes seriously out of phase with the surrounding legal order, courts may use common-law-like techniques or a 'second look' mechanism that makes contemporary political institutions reaffirm the rule before it continues to control. The argument is not simply that judges may repeal obsolete statutes. It is that legal change elsewhere can make mechanical application distort the present statutory system, while legislative inertia prevents ordinary correction. The theory is therefore a deliberately aggressive response to temporal mismatch between statutes and the later legal order. Its central difficulty is preserving democratic responsibility while giving courts enough flexibility to prevent old enactments from governing circumstances their legal world no longer resembles."
  },
  "pluralist_mainstream": {
    "opening": "You think several forms of legal argument can be legitimate at once. Text, history, precedent, structure, prudence, purpose, and other modes each answer different kinds of legal questions, so no single method should automatically control every hard case.",
    "context": "Your theory is Interpretive Pluralism in the strong sense, not merely a mixed or undecided profile. The affirmative claim is that legal reasoning contains several legitimate modes that cannot all be reduced to one master method. Constitutional text, historical practice, precedent, institutional structure, consequences, and broader constitutional commitments may each supply reasons with distinct legal force. The hard problem is not whether multiple materials exist—every serious judge uses more than one source—but how those materials relate when they conflict. Some pluralist theories treat the modes as recognizable forms of constitutional argument with their own conventions; others use a more flexible practical-reasoning approach in which their relative weight shifts with the problem. Your answers establish the legitimacy of multiple modes themselves. That makes your result more theoretical than low-theory case-by-case judging, because the plurality is part of the method rather than simply the absence of a settled hierarchy."
  },
  "pluralist_practical": {
    "opening": "You think several kinds of legal reasoning are legitimate, but you resist giving them a fixed ranking that applies to every case. Text, history, precedent, purpose, structure, and consequences can change in importance depending on the legal problem being decided.",
    "context": "Your Interpretive Pluralism is practical-reasoning oriented. A rigid pluralist system might identify several legitimate modes of legal argument but still give them relatively stable roles or priorities. Your answers are more flexible. The weight of text, history, purpose, precedent, institutional competence, and consequences can shift with the character of the dispute. That does not make the method simply intuitive or theory-free: the different forms of argument remain legally legitimate, and the judge must explain why a particular consideration deserves more weight in the case at hand. The theory therefore tries to capture a feature of actual sophisticated judging that single-method accounts often suppress—hard cases differ in what makes them hard. A statutory drafting problem, a structural constitutional dispute, and a deeply settled rights precedent may reasonably place different legal materials at the center. Your result accepts that variation as part of the method itself rather than treating it as an embarrassing departure from a master rule."
  },
  "sociological_mainstream": {
    "opening": "You think legal theory should pay close attention to what law actually does in society, not only to the formal rules written in statutes and cases. Social interests, institutions, and the real operation of doctrine can be legally important to understanding and developing the law.",
    "context": "Your theory is Sociological Jurisprudence. Its central complaint is that law on the books can look very different from law in action. Formal doctrine may announce one rule while institutions, social practices, economic relationships, and patterns of enforcement produce something quite different in people's lives. A sociological jurist therefore studies the interests legal rules organize, the institutions through which they operate, and the practical consequences they create. This is related to Pragmatism but not identical to it. Pragmatism asks what consequences should matter to a judge choosing among legal options; Sociological Jurisprudence makes the social operation of law itself a central object of legal understanding. Your answers do not require the stronger claim that nonstate social norms are themselves law. They fit the broader view that legal doctrine should be developed with a realistic understanding of the social relationships it governs rather than through abstract conceptual analysis alone."
  },
  "sociological_pluralism": {
    "opening": "You think sufficiently organized institutions outside the state can themselves form genuine legal orders. Churches, unions, universities, professional bodies, or other associations may create law for their members even when the state did not enact or formally recognize those rules.",
    "context": "Your Sociological Jurisprudence reaches the stronger position of institutional legal pluralism. Ordinary sociological approaches emphasize that lawyers should study how official law actually operates in society. Your answers question something deeper: the state's supposed monopoly on law itself. A sufficiently organized social institution can have its own offices, procedures, authority, membership rules, and normative order. On this view, those features may make it a genuine legal institution rather than merely a private group whose norms influence behavior. The difference is important. Saying that a union rule or church norm affects social life is easy; saying that it belongs to a distinct legal order challenges the conventional assumption that all law ultimately derives from state recognition. Your theory therefore expands the concept of law beyond government without grounding that expansion in free-standing morality. The key is institutional organization: law can arise from an organized normative order, and the state is one important legal order among others rather than the sole possible source of legality."
  },
  "sociological_living": {
    "opening": "You think the most important law governing much of social life can arise from the actual norms of families, businesses, associations, and communities even when those norms were never formally enacted. Jurisprudence should therefore study the living rules people really use, not only official doctrine.",
    "context": "Your theory emphasizes 'living law': the socially operative norms that actually organize relationships outside the courtroom. Formal state law remains important, but it may explain much less of everyday order than lawyers assume. Businesses develop practices, families and communities enforce expectations, professions create internal standards, and associations regulate their members through norms that may never appear in a statute or judicial opinion. The sociological claim is that jurisprudence should treat those living norms as central legal phenomena because they are where much of social ordering actually occurs. This is stronger than simply saying courts should consider practical consequences. It changes what counts as important evidence about law itself. Your answers stop short of necessarily saying every social norm is a separate legal system; the focus is on the gap between official law and the norms that actually govern social life. The judge or scholar who ignores that gap risks misunderstanding the legal order they are supposedly describing."
  },
  "sociological_free": {
    "opening": "You think authoritative legal sources should control while they genuinely answer the case, but judges should be honest when those sources run out. In a real gap, the court may need to construct a rule through disciplined inquiry into social facts, practical needs, equity, and justice rather than pretending the answer was already hidden in the text.",
    "context": "Your approach follows the idea of Free Scientific Research. It begins more conservatively than ordinary open-ended Pragmatism: enacted law, established custom, and other authoritative legal sources govern when they actually resolve the dispute. The distinctive move appears only when those sources genuinely fail. Instead of using legal fictions to pretend that a missing rule was always implicit in the text, the judge should openly construct the law through disciplined study of social facts, the practical needs of the relationship, equity, justice, and the nature of the institutions involved. That makes the theory both source-respecting and creative. It differs from Textualism, which is more reluctant to acknowledge a judicial lawmaking space, and from broad Realism, which often describes underdetermination without prescribing this particular method for filling the gap. Your result treats honest recognition of a source gap as preferable to disguising judicial creation as deduction, while still demanding a structured inquiry rather than free personal preference."
  },
  "realist_mainstream": {
    "opening": "You doubt that formal legal doctrine fully explains what judges do in genuinely hard cases. When respectable legal arguments support more than one result, background views, institutional setting, practical consequences, and other extra-doctrinal factors can help explain which answer a court actually chooses.",
    "context": "Your Legal Realism is primarily a claim about how adjudication works, not a complete theory of how judges ought to decide. Formal legal materials can be powerful, but hard appellate cases often reach court precisely because doctrine does not uniquely determine the result. In that setting, understanding outcomes requires attention to judges, institutions, practical consequences, professional habits, and other factors that conventional doctrinal analysis may leave implicit. That does not mean legal reasoning is fake or that judges simply vote their politics. The Realist point is more careful: doctrine can constrain without mechanically determining, and the reasons that explain a choice among defensible legal options may include facts outside the formal sources. Because Realism is descriptive in this sense, it can coexist with Textualism, Positivism, Pragmatism, or another normative method. Your result says something important about the limits of doctrinal explanation even if another part of your jurisprudence still tells judges what they should do once those limits appear."
  },
  "realist_fact": {
    "opening": "Your Realism extends beyond uncertainty in legal rules to uncertainty about what happened. Witness credibility, memory, trial factfinding, and the psychology of judges and juries can make legal outcomes unpredictable even if appellate doctrine were much clearer.",
    "context": "Your Legal Realism is fact-skeptical. Much Realist theory focuses on rule skepticism: hard cases arise because legal doctrine permits more than one defensible interpretation, leaving room for extra-doctrinal influences. Your answers locate another source of uncertainty earlier in the process. Courts do not apply rules to perfectly known facts; they reconstruct events from witnesses, documents, credibility judgments, imperfect memory, and human decisionmakers. Even a perfectly clear legal rule can therefore produce uncertain results because the factual premise to which the rule applies is unstable. This shifts attention away from appellate opinions and toward the trial process, where most legal disputes are actually resolved. The theory is especially skeptical of attempts to make adjudication fully predictable through better doctrine alone. Clarifying the law can reduce one kind of uncertainty, but it cannot eliminate the human problems involved in deciding what happened. Your result therefore gives psychology and factfinding a central place in any realistic account of courts."
  },
  "realist_functional": {
    "opening": "You are suspicious of abstract legal labels doing the work of an argument. When a case turns on concepts such as property, corporation, or jurisdiction, you want the court to translate the label into the concrete conduct, consequences, and policy choices the concept is being used to justify.",
    "context": "Your Legal Realism is functional and anti-conceptual. The target is a familiar kind of legal reasoning in which an abstract category appears to decide the case simply because the court has attached the category's name. A functional Realist asks what the concept actually changes in the world: who may act, who bears costs, what behavior is encouraged, and what social policy is being chosen. That does not make legal concepts useless. Categories can summarize doctrine and promote consistency. The criticism is that they can become circular when the label itself is treated as the reason for the outcome. Your answers therefore push legal analysis toward concrete institutional and social effects. The judge should expose the real choice hidden inside the doctrinal vocabulary rather than allowing words such as 'property' or 'jurisdiction' to substitute for explanation. This is a specifically Realist form of skepticism about conceptual formalism, not merely a general preference for practical consequences."
  },
  "political_constitutionalist": {
    "opening": "You think reasonable people can disagree about constitutional rights without either side acting unlawfully, and that functioning representative institutions often have the stronger claim to make those contested choices. Courts matter, but judges do not automatically deserve the final word merely because a dispute is constitutional.",
    "context": "Your theory is Political Constitutionalism. The argument for democratic authority is stronger than ordinary judicial restraint. It begins from reasonable disagreement: even citizens and officials who take rights seriously can disagree about what those rights require. When democratic institutions are functioning, giving final authority to elected representatives can better respect political equality than allowing a small group of judges to settle every contested rights question. This does not deny that constitutional rights exist or that courts can play valuable roles. Courts may interpret statutes, enforce clear legal limits, improve public reasoning, and sometimes identify rights violations. The deeper dispute is over finality and legitimacy. Why should disagreement be resolved by judicial supremacy rather than by representative politics? Your answers place the burden on strong-form judicial review to justify that transfer of authority. The theory therefore treats democratic participation and equal political voice as constitutional values in their own right, not merely as interests that courts may override whenever judges reach a different substantive judgment."
  },
  "thayerian": {
    "opening": "You think courts should keep the power of judicial review but use it only when the legislature's constitutional error is clear, not merely because judges would interpret the Constitution differently. Reasonable constitutional disagreement should usually be resolved through politics rather than judicial invalidation.",
    "context": "Your judicial-review theory is Thayerian. It differs from both judicial supremacy and a complete rejection of judicial review. Courts still interpret the Constitution independently, but the standard for invalidating legislation is highly deferential: the question is not simply whether the judges think the law is unconstitutional, but whether the legislature's contrary constitutional judgment falls outside the range of reasonable interpretation. That shifts responsibility back toward democratic institutions and citizens, who cannot treat every difficult constitutional question as something courts will resolve for them. The theory also differs from broader Political Constitutionalism. A political constitutionalist may challenge the legitimacy of strong judicial finality on grounds of democratic equality and reasonable disagreement. Thayerianism is more specifically a judicial doctrine of clear-error restraint. Your answers therefore preserve courts as constitutional actors while sharply narrowing the circumstances in which judicial disagreement is enough to displace a legislative judgment."
  },
  "popular": {
    "opening": "You think the Constitution ultimately belongs to the people rather than to courts. Judges may decide cases and enforce judgments, but constitutional meaning should remain part of democratic constitutional politics rather than becoming the exclusive property of the judiciary.",
    "context": "Your theory is Popular Constitutionalism. The central target is judicial supremacy—the idea that the Supreme Court's constitutional interpretation should become the uniquely authoritative meaning for the entire political system. Popular Constitutionalism accepts that courts decide constitutional cases, but it insists that constitutional authority ultimately remains with the people acting through political institutions, movements, elections, and public constitutional argument. That makes the theory different from ordinary majoritarian deference. The claim is not simply that legislatures should win more cases; it is that constitutional interpretation itself belongs to a broader democratic practice. It also differs from Departmentalism, which emphasizes the independent interpretive authority of coordinate branches. Your result puts the people and democratic constitutional politics closer to the center. The challenge is preserving legal stability and rights protection while refusing to let judicial doctrine become the sole legitimate language through which the Constitution can be understood."
  },
  "departmentalist": {
    "opening": "You think courts are authoritative when they decide cases, but other branches retain their own constitutional duties rather than being required to treat the Supreme Court's interpretation as the Constitution's single binding meaning for everyone.",
    "context": "Your theory is Departmentalist rather than simply anti-court. Judicial review remains real: courts interpret the Constitution, issue binding judgments, and create precedent within the judicial system. The disagreement is with judicial supremacy—the stronger claim that a Supreme Court interpretation becomes the uniquely controlling constitutional meaning for every governmental actor. Departmentalism gives coordinate branches their own constitutional responsibilities. The President and Congress may have duties to interpret the Constitution within the powers assigned to them, even when their good-faith understanding differs from judicial doctrine. That makes the theory different from Popular Constitutionalism, which locates ultimate authority more directly in the people and democratic constitutional politics. Your result is institutional: constitutional authority is distributed among departments whose judgments have different forms of legal effect. Courts remain powerful, but their power comes from judgments, remedies, and precedent rather than from a general monopoly on constitutional meaning."
  },
  "political_process": {
    "opening": "You usually leave substantive political disagreement to democratic institutions, but your deference ends when the political process itself is distorted. Courts have a stronger reason to intervene when groups are excluded, channels of change are blocked, or incumbents can entrench themselves against ordinary democratic correction.",
    "context": "Your theory changes the usual courts-versus-democracy question. Instead of asking whether judges are generally better than legislatures at deciding contested rights, Political Process theory asks whether democracy is functioning well enough to correct its own mistakes. Ordinary substantive disagreements remain mainly political. Judicial review becomes most defensible when the mechanisms of representation and political change are themselves impaired—when minorities are excluded from effective participation, channels of reform are blocked, or those in power manipulate the rules to entrench themselves. The court's role is therefore representation-reinforcing rather than generally substantive. It protects the conditions under which democratic disagreement can be resolved fairly. This explains how your result can combine a majoritarian baseline with forceful judicial intervention in particular cases. The trigger is not that judges have superior moral judgment about every right; it is that the usual democratic reason for deference has broken down. Once the process is repaired, ordinary political responsibility resumes."
  },
  "political_process_responsive": {
    "opening": "You think courts should respond to failures of democracy, but not with one fixed level of scrutiny or one standard remedy. The timing, intensity, reasoning, and relief should depend on the particular democratic blind spot and on what courts are actually capable of improving.",
    "context": "Your Political Process theory is responsive rather than one-size-fits-all. The baseline idea remains representation reinforcement: courts have their strongest reason to intervene when ordinary politics cannot reliably correct itself. Your distinctive move is to reject a single judicial response for every democratic failure. Exclusion of a politically weak minority, legislative inertia, incumbent entrenchment, and concentrated monopoly power can create different problems and may call for different forms of review. A court should therefore calibrate how aggressively it acts, what reasons it demands, how quickly it intervenes, and how broad a remedy it issues to the specific dysfunction and to its own institutional capacity. That makes judicial review more adaptive but also more demanding to justify. The court cannot simply invoke 'democracy' as a reason for activism; it has to identify the failure it is addressing and explain why its chosen intervention is likely to make the democratic system work better rather than displace politics unnecessarily."
  },
  "minimalist": {
    "opening": "You think courts should decide no more than they need to decide. Narrow holdings, limited remedies, and leaving broader theories unresolved can protect rights while preserving room for later courts, democratic institutions, and social learning.",
    "context": "Your theory is Judicial Minimalism. The central question is not whether courts should enforce constitutional law at all, but how much law they should make when they do. A minimalist prefers decisions that are narrow in scope and often shallow in theoretical depth: resolve the concrete dispute without unnecessarily announcing a comprehensive rule for every future case. That can make agreement easier among judges who disagree about first principles, reduce the cost of judicial mistakes, and leave contested questions open to further democratic or legal development. Minimalism therefore should not be confused with simple judicial weakness. A court can invalidate government action while still writing a narrow opinion and tailoring relief closely to the problem before it. Your result treats uncertainty as a reason for modest doctrinal steps rather than an invitation either to surrender judicial review or to settle the entire constitutional controversy at once."
  },
  "minimalist_passive": {
    "opening": "Your judicial restraint goes beyond narrow opinions. You think timing, justiciability, and strategic avoidance can themselves be legitimate tools, allowing courts to decline or postpone constitutional decisions when immediate resolution would needlessly intensify the conflict.",
    "context": "Your Minimalism is built around the passive virtues. Ordinary Judicial Minimalism asks courts to decide cases narrowly and shallowly once they reach the merits. Your answers give avoidance itself a larger role. Standing, ripeness, political-question doctrines, procedural timing, and other devices can let courts postpone or sidestep a constitutional confrontation even when a broad merits ruling would be possible. The theory responds to the counter-majoritarian difficulty by recognizing that when courts decide can matter almost as much as what they decide. Delay can give political institutions time to act, allow public understanding to develop, or prevent the judiciary from prematurely freezing a deeply contested issue into constitutional law. The obvious danger is that avoidance can also leave rights unprotected or disguise a substantive choice as procedure. Your result accepts that risk because it treats judicial timing and restraint as part of constitutional statecraft rather than as mere technical barriers to reaching the merits."
  },
  "weak_form": {
    "opening": "You think courts can decide rights independently without giving them an entrenched monopoly on the final constitutional word. A constitutional system may authorize legislatures to respond to a judicial rights ruling through a structured legal process short of formal constitutional amendment.",
    "context": "Your judicial-authority theory is weak-form or dialogic. Strong-form judicial review gives courts the final legal word unless the Constitution is formally amended. Pure legislative supremacy gives elected institutions that authority instead. Your answers occupy a middle institutional design. Courts still assess rights independently and their judgments have immediate legal force, but the constitutional system can give legislatures a prescribed mechanism to reconsider the issue and enact a contrary rule without going through the full amendment process. The point is not informal political pressure on courts; the dialogue is built into the legal structure. That arrangement tries to preserve judicial reason-giving and rights scrutiny while preventing constitutional disagreement from becoming the exclusive property of judges. Its success depends heavily on the design of the legislative response mechanism and on political conditions: if override is too easy, rights review may become symbolic; if too difficult, the system begins to resemble strong-form judicial supremacy."
  },
  "formalist_mainstream": {
    "opening": "You think legal form matters because rules, categories, assigned powers, and prescribed procedures constrain decision-makers before the hard case arrives. Efficiency or fairness in a particular dispute is not enough to ignore a boundary the legal system has already drawn.",
    "context": "Your Formalism is best understood as a theory of constraint rather than a commitment to any one source of law. Formalism can operate in different domains: a judge may prefer rule-like doctrine, insist on categorical separation of governmental powers, or demand that legally prescribed procedures be followed even when a more flexible arrangement would work better. The common idea is that form has value precisely because it limits all-things-considered judgment in the particular case. A rule that can be bent whenever the decisionmaker thinks the result is unattractive is not doing much constraining work. That does not make Formalism synonymous with Originalism or Textualism. A nonoriginalist can favor rules, and a textualist can favor balancing. Your result is about the role of legal form itself: predictability, notice, institutional boundaries, and disciplined authority are worth some loss of case-specific fit because they reduce the power of officials to improvise according to their own view of the best outcome."
  },
  "formalist_nondelegation": {
    "opening": "You think some governmental powers must remain with the institution the Constitution assigned them to, even when Congress clearly wants to transfer the decision elsewhere. Efficiency and explicit authorization cannot cure a delegation that crosses the constitutional boundary itself.",
    "context": "Your structural Formalism is especially strong on nondelegation. Many judges who care about separation of powers are willing to let Congress authorize agencies to make major policy choices so long as Congress supplies an adequate legal standard and retains political accountability. Your answers take a harder constitutional view. Some decisions are legislative in a sense that matters to the Constitution, and Congress cannot transfer them merely by writing the delegation clearly. That distinguishes constitutional nondelegation from doctrines such as a clear-statement rule or a major-questions canon, which may require Congress to speak unmistakably before an agency may act but still accept the delegation once Congress has done so. Your theory treats the allocation of power itself as legally binding. The difficult question is defining which policymaking decisions are so legislative that they cannot be delegated without making modern administration impossible. Your result accepts more of that structural risk in order to preserve a sharper constitutional boundary around lawmaking power."
  },
  "formalist_unitary": {
    "opening": "You think executive power carries a strong principle of presidential control. Congress may create offices and assign duties, but it cannot fully insulate executive administration from the President's authority to supervise and direct the execution of federal law.",
    "context": "Your structural theory follows the unitary-executive side of a major Article II dispute. The question is not simply whether presidents should be politically accountable for administration. It is whether the Constitution's grant of executive power gives the President legal authority to control the judgments of executive officers, including officials whom Congress would prefer to make independent. A strong unitary view treats executive administration as ultimately subject to presidential direction; a more accommodationist view allows Congress to assign some lawful judgments to subordinate officers without making every such decision replaceable by the President. Your result favors the first account. That fits a broader separation-of-powers Formalism because the branch assignment itself carries legal consequences: if a function is executive, presidential control is part of the constitutional structure rather than one optional arrangement among several workable designs. The modern controversy is how far that principle extends across independent agencies, removal protection, adjudication, and professional administration."
  },
  "formalist_rules": {
    "opening": "You think rules are valuable partly because they deny judges permission to reach the best all-things-considered result in every case. Predictability and constraint are worth some bad edge cases if the alternative is letting each decisionmaker reopen the merits whenever a rule feels too rigid.",
    "context": "Your Formalism is centered on rules rather than primarily on historical interpretation or separation of powers. The point of a genuine rule is that it screens off some considerations that would otherwise seem relevant. If a speed limit, jurisdictional deadline, or constitutional category can always be relaxed whenever a judge thinks the particular case deserves an exception, the rule stops constraining the judge in the situations where constraint matters most. Your answers therefore accept some mismatch between general rules and individual justice as the price of predictability, equal treatment, administrability, and reduced discretion. This distinguishes rule Formalism from a simple preference for clear drafting. It is a theory about decisionmaking: legal rules should sometimes require an outcome that the official would not choose if free to weigh everything from scratch. Your result is especially skeptical of balancing tests that make the strength of a legal right depend on a fresh case-by-case assessment of competing interests."
  },
  "functionalist_mainstream": {
    "opening": "You think separation of powers should protect accountability, checks, and each branch's basic capacity rather than enforce rigid institutional boxes for their own sake. Some overlap is constitutionally acceptable when the arrangement remains workable and does not destroy the core role of another branch.",
    "context": "Your structural theory is Functionalist. The central disagreement with separation-of-powers Formalism is not whether constitutional structure matters; both sides think it does. The dispute is how that structure should be translated into legal rules. A Formalist is more likely to ask whether a power belongs to a constitutionally assigned category and whether another institution has crossed that boundary. A Functionalist asks what the arrangement actually does: does it concentrate power dangerously, undermine accountability, disable a branch from performing its core job, or instead create a workable system of checks? That makes your theory more tolerant of modern administrative arrangements that combine rulemaking, enforcement, and adjudicative functions. The tolerance is not unlimited. A system that effectively destroys political accountability or transfers a branch's essential constitutional role can still be invalid. Your result treats institutional design as a practical constitutional problem rather than assuming that every overlap is unlawful simply because it does not fit a clean organizational chart."
  },
  "functionalist_supervisory": {
    "opening": "You think modern administration can be constitutionally legitimate without either rigidly separating every governmental function or giving the President plenary control over every official judgment. The Constitution instead requires a system of lawful supervision and accountability across the administrative state.",
    "context": "Your Functionalism is supervisory rather than simply permissive. You accept that modern agencies can combine functions and exercise substantial delegated authority, but you do not treat that as a constitutional blank check. The legal system still needs institutions that ensure administration remains lawful, reasoned, and accountable. What makes your view distinctive is separating supervision from presidential control. A strong unitary-executive theory tends to identify constitutional accountability with the President's power to direct subordinate executive officials. Your answers allow Congress to assign some independent lawful judgments while still requiring meaningful oversight, review, and a duty to ensure faithful execution. Agencies themselves can also participate in constitutional implementation through internal procedures, norms, and reason-giving obligations. The result is a Functionalist administrative constitutionalism: legitimacy comes from a network of supervision and legal accountability rather than from either strict departmental separation or a single chain of presidential command."
  },
  "functionalist_admin": {
    "opening": "You think administrative adjudication can be constitutionally legitimate when Congress authorizes it and courts retain appropriate review. Assigning some disputes to agency adjudicators does not automatically violate the judicial role merely because the decision has legal consequences.",
    "context": "Your Functionalism extends to administrative adjudication. A hard structural Formalist can argue that imposing serious civil liability is an exercise of judicial power that belongs in an Article III court, even if Congress created an agency tribunal and allowed later judicial review. Your answers are more accommodating. You are willing to look at the institutional arrangement as a whole: what kind of dispute is being decided, how Congress structured the program, what independence and procedures the adjudicator has, and how meaningful the eventual court review is. That does not mean every administrative tribunal is valid. The arrangement can still threaten impartiality, accountability, or the constitutional role of courts. But you reject the premise that combining adjudicative functions with administration is categorically unlawful. Your result therefore treats administrative adjudication as a problem of functional safeguards and institutional design rather than a simple question of whether the label 'judicial' can be attached to the task."
  },
  "proportionalist_mainstream": {
    "opening": "You prefer a structured form of balancing when government limits a right. The government should identify a legitimate goal, show that its measure actually advances that goal, explain why a less restrictive approach would not work, and justify the remaining burden on the right.",
    "context": "Your theory is Proportionalist rather than merely pro-balancing. Generic balancing can sound like a judge places interests on opposite sides of a scale and announces which feels weightier. Proportionality tries to make that judgment more structured and transparent. The government must begin with a legitimate objective, use a measure genuinely connected to that objective, show that no less rights-restrictive workable alternative would achieve it comparably well, and finally justify the remaining burden in light of the public benefit. Rights therefore operate neither as absolute categorical rules nor as interests that can be overridden by any convenient policy reason. The method demands explicit justification at each stage. Its defenders see that structure as a way to discipline judicial judgment and force government to explain itself; critics worry that the final weighing still gives courts substantial discretion over contested values. Your answers place more trust in structured reason-giving than in bright-line rights that decide the case without examining fit, necessity, and burden."
  },
  "proportionalist_nonpositive": {
    "opening": "You think structured proportionality is not just a useful policy tool; it reflects the legal force of principles whose weight and moral justification are part of the law itself. Rights therefore require reasoned comparison rather than simple source-following or categorical rules.",
    "context": "Your Proportionalism sits inside a Non-Positivist account of law. That matters because it changes what the proportionality test is doing. On a purely source-based account, a legislature or constitution might simply enact a balancing standard and courts would apply it because positive law tells them to. Your answers give legal principles a deeper role: rights and competing public reasons can have legal force because moral correctness or principle is part of legal reasoning itself. Proportionality then becomes a method for working out the demands of those principles in concrete cases. The government must justify purpose, fit, necessity, and the final burden rather than merely point to a formally valid source of authority. This approach is especially far from rule Formalism, where rights are often protected by categories that try to exclude case-by-case moral weighing. Your result trusts structured practical reasoning to make principle-based rights legally operational while insisting that the structure of the test disciplines what would otherwise be open-ended balancing."
  },
  "traditional_equity": {
    "opening": "You think courts do not gain a general power to solve a legal problem however effectively they can. Even when broader relief would work better, equitable remedies should ordinarily stay within historically grounded forms and protect the parties before the court.",
    "context": "Your most distinctive theory concerns remedies rather than the underlying merits. The issue is what lawful judicial power remains after a court has already decided that the government violated the law. A broad remedial approach asks what order will effectively end the violation, potentially extending relief to nonparties or restructuring an institution. Your answers treat that effectiveness inquiry as legally incomplete. Equity is itself a historically bounded form of judicial power, with traditional remedies, parties, and limits that courts do not acquire authority to transcend simply because a broader order would solve the problem more efficiently. That makes your position narrower than generic judicial Minimalism. The claim is not merely that small remedies are prudent; it is that remedial form can be a legal limit on judicial power. This distinction matters because a judge can be aggressive on the merits—readily finding a rights violation—while still concluding that the Constitution or traditional equitable authority permits only party-specific relief."
  },
  "universal_relief": {
    "opening": "You think judicial relief is not categorically limited to protecting only the named plaintiff. When a government policy operates generally, a court may sometimes lawfully issue relief that protects affected nonparties rather than forcing everyone to bring the same lawsuit separately.",
    "context": "Your distinctive position concerns the scope of equitable relief. A strict party-specific theory treats a federal court's job as remedying the legal injury of the plaintiffs before it; broader protection for strangers to the case risks turning the court into a general supervisor of government policy. Your answers reject a categorical version of that limit. When the challenged rule operates across the board, broader relief may sometimes be justified by the nature of the violation and the remedial authority the court is exercising. That does not automatically commit you to structural reform or continuing judicial management. Universal relief can still be a comparatively focused order aimed at preventing the government from enforcing one unlawful policy more broadly. The theoretical dispute is therefore about the relationship between the parties, the government's general conduct, and the historic scope of equitable power. Your result gives courts more remedial reach than traditional party-specific equity while leaving open how often that reach should actually be used."
  },
  "constitutional_common_law": {
    "opening": "You think courts may sometimes create legal rules that go beyond the Constitution's bare minimum in order to make a constitutional guarantee workable. Those implementing doctrines can be real law while remaining conceptually distinct from the underlying constitutional command.",
    "context": "Your distinctive theory is constitutional common law. Constitutional adjudication often uses doctrines that are broader or more administrable than the underlying constitutional right itself: prophylactic rules, evidentiary protections, or implementing standards designed to make the right effective in practice. Your answers treat those doctrines as legally legitimate while insisting on a conceptual distinction between the Constitution and the judicial rule that implements it. That distinction matters because the implementing rule may be revised, narrowed, displaced, or treated differently from the constitutional minimum it protects. The theory therefore avoids a false choice between saying every protective doctrine is literally required by the constitutional text and saying courts have no authority to create such doctrines at all. It also fits naturally with Legal Process and Common-Law approaches that recognize a judicial role in elaborating workable law. Your result gives courts genuine law-development authority, but in a form that remains analytically separate from changing the Constitution itself."
  },
  "remedial_equilibration": {
    "opening": "You think rights and remedies can shape one another. If a very broad understanding of a constitutional right would require remedies that courts regard as intolerably costly or intrusive, those remedial consequences may legitimately influence how the right itself is defined.",
    "context": "Your distinctive position is remedial equilibration. Legal doctrine often presents rights and remedies as separate stages: first determine the constitutional right, then decide how to remedy its violation. Your answers reject that clean sequence. Courts understand substantive rights partly in light of what enforcing those rights would require. If one interpretation would predictably demand extraordinarily intrusive institutional supervision, massive financial costs, or remedies courts consider practically impossible, that consequence can feed back into the definition of the right itself. The relationship can also run in the other direction: stronger substantive rights may push courts toward more powerful remedies. This is not simply Pragmatism about consequences. It is a specific theory of constitutional doctrine in which the scope of right and remedy develops reciprocally. The approach helps explain why courts sometimes narrow or reshape substantive doctrine when remedial stakes become extreme, but it also raises a hard question: whether practical concerns about judicial capacity should be allowed to shrink rights that would otherwise have a broader legal meaning."
  },
  "structural_reform": {
    "opening": "You think a court can sometimes do more than order the government to stop one unlawful act. When the violation is built into an institution, effective adjudication may require structural reform, continuing supervision, and judicial oversight of the process of bringing the institution into legal compliance.",
    "context": "Your most distinctive judicial-power commitment concerns structural remedies. Traditional litigation imagines a dispute between parties, followed by a judgment that tells the defendant what it owes the plaintiff. Structural-reform litigation treats some constitutional violations as institutional problems: a school system, prison, police department, or public bureaucracy may be organized in a way that continuously produces illegality. In that setting, a one-time party-specific order may leave the underlying violation intact. Your answers therefore allow courts to reshape policies, require institutional plans, monitor compliance, and retain jurisdiction over time. The theory treats adjudication as a means of vindicating public legal values through institutional reform, not merely resolving a private dispute. Its central controversy is institutional competence and democratic legitimacy. A court may be uniquely positioned to insist on compliance with rights, but judges can also become long-term managers of complex systems they do not operate. Your result accepts more of that managerial role when narrower remedies would not actually end the violation."
  },
  "nonpos_generic": {
    "opening": "You think recognized legal sources do not fully exhaust what law can require, but your answers do not reduce that claim to one simple moral override. Legal principle has a role that a purely source-based account cannot completely explain.",
    "context": "Your result belongs in the broad Non-Positivist family, but the important point is what that does and does not establish. You reject the claim that social sources alone always settle the existence and content of law. That still leaves several very different theories open. Interpretivists say legal principles emerge from the moral reading that best fits and justifies institutional practice. Natural-Law theories connect legality to objective practical reason while often preserving a strong settlement role for positive law. Other one-system theories treat legal rights as genuine moral rights shaped by institutional action. These are not interchangeable ways of saying that morality matters. They disagree about how moral facts enter law, how much source-based settlement survives, and whether hard cases contain preexisting legal answers. Your answers establish the rejection of source-only legality more clearly than they establish one narrower mechanism, so the honest description stays at that broader theoretical level."
  },
  "positivist_command": {
    "opening": "You understand law in strongly sovereign terms: legal rules are fundamentally commands issued by a determinate political authority, backed by the prospect of sanctions and sustained by habitual obedience. That is a much older and harder-edged form of Positivism than the social-rule theories that dominate modern legal philosophy.",
    "context": "Your Positivism follows the command-theory tradition. The basic idea is that law is best understood as the command of a sovereign to subjects, backed by sanctions and supported by a general habit of obedience. This was enormously influential in nineteenth-century analytic jurisprudence, but most modern Positivists moved away from it. Contemporary theories usually emphasize the practices through which officials identify valid law, the normative structure of legal systems, or the institutional plans through which legal authority is organized. The command model can struggle to explain continuity across changes of government, legal powers that do not look like threats, and constitutional rules that bind officials themselves. Your answers nevertheless take the sovereign-command structure seriously: what makes law distinctive is not moral merit but an institutional relationship of authoritative direction and obedience. That places you inside Legal Positivism while also locating you in a historically important branch that is no longer its mainstream form."
  },
  "positivist_pure": {
    "opening": "You think legal validity is structured through a hierarchy of authorizing norms: one rule is valid because a higher legal rule authorizes its creation, with the system ultimately unified by a presupposed basic norm rather than by morality, sovereign command, or ordinary social habit alone.",
    "context": "Your Positivism follows the Pure Theory of Law. Instead of explaining law mainly through a sovereign's commands or through the social rule officials accept for identifying law, this theory emphasizes the normative hierarchy of the legal system. A regulation is valid because a statute authorizes it; the statute is valid because the constitution authorizes its creation; and the unity of the system ultimately depends on a presupposed basic norm that lets the chain of legal validity operate as one normative order. The theory deliberately tries to keep legal science 'pure' of moral, political, and sociological explanation when describing validity. That makes your position a distinctive branch of Positivism rather than its ordinary modern form. Social facts still matter because legal acts occur in institutions, but validity is explained through the structure of authorizing norms, not simply through coercion or through a general moral judgment about whether the rule deserves obedience."
  },
  "positivist_planning": {
    "opening": "You understand a legal system as a system of shared social planning. Legal institutions create, revise, and apply plans for coordinating conduct, and the authority of law is best explained through that planning structure rather than through sovereign commands or moral correctness.",
    "context": "Your Positivism follows Planning Theory. The central idea is that law solves complex social problems by creating shared plans: institutions decide who has authority, which procedures must be followed, and what rules will guide conduct when individuals would otherwise disagree about what to do. A legal system therefore resembles an organized planning structure more than a collection of threats or isolated source rules. This preserves the Positivist claim that legal validity ultimately depends on social facts and institutional practices rather than on moral merit, but it offers a different explanation of those practices. The theory is especially useful for explaining how law coordinates large groups, delegates authority, and creates plans about how future plans will be made. Your result is therefore source-based without being merely conventionalist: the social facts matter because they establish and operate a shared planning system. Moral reasons may explain why a plan is good or why people should follow it, but they are not what makes the plan part of the law."
  },
  "legal_constitutionalist": {
    "opening": "You give courts a strong independent responsibility to enforce constitutional rights and legal limits against political majorities. Judicial review is not merely a backstop for obvious mistakes; constitutional law can require courts to reach their own judgment even when elected institutions strongly disagree.",
    "context": "Your result reflects a strong legal-constitutional view of judicial review. The central idea is that constitutional rights and structural limits are law, and courts have an independent duty to enforce that law rather than treating reasonable political disagreement as a sufficient reason to defer. That distinguishes your position from Thayerian restraint, which asks courts to uphold legislation unless the constitutional error is clear, and from Political Constitutionalism, which gives representative institutions a stronger claim to final authority under conditions of reasonable rights disagreement. Strong judicial review does not by itself decide how constitutional meaning should be found: an Originalist, Living Constitutionalist, Textualist, or principle-based theorist can each support robust judicial enforcement for different reasons. Your result is therefore primarily about institutional responsibility. Once a legal right or boundary is established, political popularity does not reduce the court's obligation to enforce it."
  }
});

  const SPECIAL_IDS = new Set(["unusable_response","incoherent_response","outcome_driven_left","outcome_driven_right"]);
  const isOriginalist = (id) => ["originalist","public_meaning_originalist","original_intent_originalist","original_methods_originalist","framework_originalist"].includes(id);
  const has = (traits, key, min = 0.5) => Number(traits?.[key] || 0) >= min;
  const axis = (scores, id) => Number(scores?.[id] ?? 50);

  const OPENINGS = Object.freeze({
    constraint_correction: "You have a constraint-centered view of judging: courts should enforce law already made rather than improve it through present-day judgment. That makes you strict about enacted language, historically fixed constitutional meaning, and legal boundaries on government. But you are not deferential once government crosses a genuine legal line, and you are comparatively willing to overrule precedent that keeps the legal mistake in place.",
    constraint_settlement: "You think judges are constrained by law that predates the case, but you also treat legal settlement as part of that constraint. Enacted language and historically grounded law matter, yet precedent, reliance, and continuity can limit how aggressively a court should correct old mistakes. Your restraint therefore comes from both fidelity to legal sources and respect for the legal order that has grown around them.",
    constraint_general: "You have a strongly constraint-centered view of judging: courts should identify legal choices already made and resist improving them through present-day judgment. Text, historically grounded meaning, rules, or institutional boundaries do much of the constraining work. That can make you both restrained and assertive: restrained about changing law, but willing to enforce a genuine legal limit even when the political result is inconvenient.",
    developmental_settlement: "You think constitutional law can develop, but you want that development to occur through law rather than free judicial updating. Precedent, practice, and accumulated institutional experience therefore matter heavily to what later judges inherit. You are more interested in continuity and legal settlement than in starting each case from first principles, while still accepting that constitutional doctrine can change as the legal tradition develops.",
    developmental_rights: "You think constitutional commitments can develop over time and that courts have a real responsibility to make those commitments effective. Later doctrine, experience, and changing understandings can matter without turning constitutional judging into simple preference. Your approach is therefore developmental rather than historically fixed, but it still asks judges to justify change through legal principle rather than treating contemporary values alone as enough.",
    moral_settlement: "You think moral principles help explain the authority and limits of law, but you do not treat morality as a standing permission for judges to replace positive law. One of law's central jobs is to settle questions that reasonable moral judgment leaves open. That makes your judging morally grounded yet unusually attentive to enacted rules, institutional authority, and the need for stable legal settlement.",
    institutional_process: "You think faithful judging depends not only on the best abstract interpretation, but on how the legal system divided responsibility among institutions. Text, precedent, expertise, delegated authority, and reason-giving can all matter because courts are not the only bodies doing legal work. Your method is constrained without being rigid: the question is often not simply what answer is best, but whose lawful job it is to give it.",
    adaptive_pragmatic: "You think hard cases sometimes leave genuine room for judgment, and you want that judgment to be candid about practical consequences and institutional workability. Rules and precedent matter when they make law predictable and coherent, but neither deserves protection simply because it is old or formal. Your judging is therefore comparatively adaptive: legal doctrine should work in the institutions and social conditions where it actually operates.",
    democratic_process: "You usually leave ordinary substantive disagreement to democratic politics, but that deference is conditional on politics being able to correct itself. Courts gain a stronger role when representation is distorted, channels of change are blocked, or power becomes self-entrenching. Even then, your instinct is to target the democratic failure rather than convert every contested political question into a broad judicial mandate.",
    democratic_deferential: "You give democratic institutions substantial room when constitutional meaning is reasonably contestable. Courts still have a legal role, but judicial disagreement alone does not automatically justify displacing a political judgment. Your theory therefore treats constitutional restraint as more than personal modesty: it reflects a view about institutional legitimacy and who should bear responsibility for resolving difficult disagreements in a constitutional democracy.",
    rights_structured: "You give courts a strong responsibility to enforce legal rights even against political majorities, but you prefer that judgment to be disciplined rather than intuitive. Purpose, fit, necessity, or legal principle can matter to the analysis, and broad remedies may be justified when a violation is genuinely systemic. Your approach trusts reasoned judicial judgment more than categorical rules that end the inquiry before competing claims are examined.",
    rule_formalist: "You think legal rules are valuable partly because they stop judges and officials from reconsidering everything in light of the particular case. Predictability, notice, and institutional boundaries are worth some imperfect outcomes if the alternative is discretionary reweighing whenever a rule feels inconvenient. Your judging therefore accepts harder edges than a balancing-oriented approach, especially when flexibility would weaken the rule's ability to constrain the decisionmaker.",
    realist: "You are skeptical that formal legal doctrine fully explains what happens in genuinely hard cases. Legal materials can constrain without mechanically determining the result, leaving room for facts about judges, institutions, practical consequences, or social context to matter. That does not tell you to ignore law; it tells you that an honest account of judging must distinguish the reasons courts give from the broader forces that can shape difficult decisions.",
    sociological: "You think law should be understood through what it actually does in social institutions, not only through rules written in statutes and cases. Real practices, social interests, and the norms people live under can reveal gaps between law on the books and law in action. Your judging therefore pays unusual attention to how doctrine operates in the relationships and institutions it is supposed to govern.",
    low_theory: ROUTES.low_theory.opening
  });

  function selectOpeningId(classification, scores = {}) {
    const id = classification?.identity?.id || "mixed_jurisprudence";
    const t = classification?.traits || {};
    if (SPECIAL_IDS.has(id)) return null;
    if (id === "mixed_jurisprudence") return "low_theory";

    if (id === "legal_realist") return "realist";
    if (id === "sociological_jurist" || has(t,"method.law_in_action",0.65) || has(t,"source.institutional_legal_pluralism",0.5)) return "sociological";
    if (id === "natural_lawyer" || id === "common_good_constitutionalist" ||
        (has(t,"source.objective_morality",0.5) && has(t,"source.positive_law_settlement",0.4)))
      return "moral_settlement";
    if (id === "political_process_jurist" || id === "elyan" || has(t,"posture.process_reinforcement",0.5))
      return "democratic_process";
    if (id === "political_constitutionalist" || id === "thayerian" || id === "popular_constitutionalist" ||
        id === "departmentalist" || axis(scores,"post") >= 72)
      return "democratic_deferential";
    if (id === "legal_process_theorist" || has(t,"method.institutional_competence",0.5) ||
        has(t,"method.agency_interpretive_autonomy",0.5) ||
        (id === "textualist" && has(t,"separation.interpretive_accommodation",0.5)))
      return "institutional_process";
    if (id === "proportionalist" || has(t,"form.proportionality",0.5) ||
        (axis(scores,"post") <= 30 && axis(scores,"form") <= 32))
      return "rights_structured";
    if ((id === "living_constitutionalist" || id === "common_law_constitutionalist" || axis(scores,"time") <= 32) &&
        axis(scores,"prec") >= 62)
      return "developmental_settlement";
    if (id === "living_constitutionalist" || id === "common_law_constitutionalist" || axis(scores,"time") <= 28)
      return "developmental_rights";
    if (id === "pragmatist" || id === "purposivist" ||
        (axis(scores,"cons") <= 32 && axis(scores,"form") <= 38))
      return "adaptive_pragmatic";

    const constrained = axis(scores,"cons") >= 66 || axis(scores,"time") >= 66 ||
      axis(scores,"separ") >= 66 || axis(scores,"form") >= 66;
    if (constrained) {
      if (axis(scores,"prec") <= 32) return "constraint_correction";
      if (axis(scores,"prec") >= 68) return "constraint_settlement";
      if (id === "formalist" && axis(scores,"form") >= 72) return "rule_formalist";
      return "constraint_general";
    }
    if (id === "formalist" || axis(scores,"form") >= 74) return "rule_formalist";
    return "low_theory";
  }

  function buildOpening(classification, scores = {}) {
    const id = classification?.identity?.id || "mixed_jurisprudence";
    if (id === "unusable_response") return ROUTES.special_unusable.opening;
    if (id === "incoherent_response") return ROUTES.special_incoherent.opening;
    if (id === "outcome_driven_left" || id === "outcome_driven_right") return ROUTES.special_outcome.opening;
    const openingId = selectOpeningId(classification, scores);
    return OPENINGS[openingId] || OPENINGS.low_theory;
  }

  function selectContextId(classification, scores = {}) {
    const id = classification?.identity?.id || "mixed_jurisprudence";
    const t = classification?.traits || {};

    if (id === "unusable_response") return "special_unusable";
    if (id === "incoherent_response") return "special_incoherent";
    if (id === "outcome_driven_left" || id === "outcome_driven_right") return "special_outcome";

    // Originalism is selected from actual Originalist propositions, not merely
    // from the winning noun.
    const originalismEstablished =
      isOriginalist(id) ||
      has(t,"time.originalism_independent_authority",0.5);
    if (originalismEstablished) {
      if (id === "original_intent_originalist" || has(t,"time.original_intent",0.55)) {
        if (has(t,"time.construction_zone",0.5)) return "oi_construction";
        if (has(t,"time.intent_as_meaning",0.5)) return "oi_semantic";
        return "oi_mainstream";
      }
      if (id === "original_methods_originalist" || has(t,"time.original_methods",0.5)) return "opm_methods";
      if (id === "framework_originalist" || has(t,"time.construction_zone",0.5)) return "opm_construction";
      if (has(t,"source.objective_morality",0.5) && has(t,"source.positive_law_settlement",0.45))
        return "opm_higher_law";
      if (has(t,"time.original_law",0.5)) return "opm_original_law";
      if (has(t,"time.intratextualism",0.5)) return "opm_intratextual";
      if (has(t,"time.construction_zone",0.5)) return "opm_construction";
      if (has(t,"precedent.correctness_first",0.72) && axis(scores,"prec") <= 28) return "opm_correction";
      if (has(t,"precedent.stability",0.65) && axis(scores,"prec") >= 66) return "opm_settlement";
      if (id === "originalist" && !has(t,"time.public_meaning",0.5)) return "originalist_generic";
      return "opm_mainstream";
    }

    // Living / common-law constitutional development.
    if (id === "common_good_constitutionalist" || has(t,"method.common_good",0.5)) return "common_good";
    if (id === "common_law_constitutionalist" || has(t,"time.common_law_development",0.55)) {
      if (has(t,"source.common_law_fundamental_rights",0.5)) return "common_law_strong_rights";
      if (has(t,"source.morality_incorporated",0.5) || axis(scores,"sorc") >= 65) return "common_law_source_bound";
      if (has(t,"time.ordered_liberty_tradition",0.5)) return "common_law_tradition";
      return "common_law_mainstream";
    }
    if (id === "living_constitutionalist" || has(t,"time.living_content",0.7)) {
      if (has(t,"time.democratic_constitutionalism",0.5)) return "living_democratic";
      if (has(t,"time.transformative_constitutionalism",0.5)) return "living_transformative";
      if (has(t,"time.constitutional_moments",0.5)) return "living_moments";
      return "living_mainstream";
    }

    // Source-of-law theories.
    if (id === "natural_lawyer") {
      if (has(t,"source.strong_natural_law",0.5)) return "natural_law_strong";
      return "natural_law_mainstream";
    }
    if (id === "interpretivist" || id === "dworkinian") return "interpretivist";
    if (id === "fullerian") return "fullerian";
    if (id === "nonpositivist" || id === "moral_impact_theorist" || id === "radbruchian") {
      if (id === "moral_impact_theorist" || has(t,"source.moral_impact",0.5)) return "nonpos_moral_impact";
      if (has(t,"source.moral_practice",0.5)) return "nonpos_moral_practice";
      if (id === "radbruchian" || has(t,"source.extreme_injustice",0.5)) return "nonpos_extreme";
      return "nonpos_generic";
    }
    if (id === "positivist" || id === "inclusive_positivist" || id === "exclusive_positivist") {
      if (has(t,"source.command_theory",0.5)) return "positivist_command";
      if (has(t,"source.basic_norm",0.5)) return "positivist_pure";
      if (has(t,"source.planning_theory",0.5)) return "positivist_planning";
      if (has(t,"source.normative_positivism",0.5)) return "positivist_normative";
      if (id === "inclusive_positivist" || has(t,"source.morality_incorporated",0.5)) return "positivist_inclusive";
      if (id === "exclusive_positivist" || has(t,"source.source_thesis",0.5)) return "positivist_exclusive";
      return "positivist_mainstream";
    }

    // Statutory / adjudicative methods.
    if (id === "textualist") {
      if (has(t,"method.categorical_textual_rights",0.5)) return "textualist_categorical";
      if (has(t,"constraint.contextual_textualism",0.5) &&
          (has(t,"separation.interpretive_accommodation",0.5) || has(t,"precedent.settlement",0.55)))
        return "textualist_institutional";
      if (has(t,"constraint.enacted_bargain",0.55)) return "textualist_bargain";
      return "textualist_mainstream";
    }
    if (id === "intentionalist") {
      if (has(t,"method.congress_aware_interpretation",0.5)) return "intentionalist_congress";
      if (has(t,"constraint.imaginative_reconstruction",0.5)) return "intentionalist_imaginative";
      return "intentionalist_mainstream";
    }
    if (id === "purposivist") {
      if (has(t,"form.proportionality",0.5)) return "purposivist_proportional";
      return "purposivist_mainstream";
    }
    if (id === "legal_process_theorist") {
      if (has(t,"method.agency_interpretive_autonomy",0.5)) return "legal_process_agency";
      if (has(t,"method.neutral_principles",0.5)) return "legal_process_neutral";
      return "legal_process_mainstream";
    }
    if (id === "pragmatist") {
      if (has(t,"method.statutory_obsolescence",0.5)) return "pragmatist_obsolescence";
      return "pragmatist_mainstream";
    }
    if (id === "interpretive_pluralist") {
      if (has(t,"method.practical_reasoning",0.5)) return "pluralist_practical";
      return "pluralist_mainstream";
    }
    if (id === "sociological_jurist") {
      if (has(t,"source.institutional_legal_pluralism",0.5)) return "sociological_pluralism";
      if (has(t,"method.living_law",0.5)) return "sociological_living";
      if (has(t,"method.free_scientific_research",0.5)) return "sociological_free";
      return "sociological_mainstream";
    }
    if (id === "legal_realist") {
      if (has(t,"realism.fact_skepticism",0.5)) return "realist_fact";
      if (has(t,"realism.functional_anti_conceptual",0.5)) return "realist_functional";
      return "realist_mainstream";
    }

    // Judicial authority.
    if (id === "legal_constitutionalist") return "legal_constitutionalist";
    if (id === "thayerian") return "thayerian";
    if (id === "political_constitutionalist" || id === "waldronian") {
      if (has(t,"posture.weak_form",0.5)) return "weak_form";
      return "political_constitutionalist";
    }
    if (id === "popular_constitutionalist") return "popular";
    if (id === "departmentalist") return "departmentalist";
    if (id === "political_process_jurist" || id === "elyan") {
      if (has(t,"posture.responsive_review",0.5)) return "political_process_responsive";
      return "political_process";
    }
    if (id === "minimalist" || id === "bickelian") {
      if (has(t,"posture.passive_virtues",0.5)) return "minimalist_passive";
      if (has(t,"posture.weak_form",0.5)) return "weak_form";
      return "minimalist";
    }
    if (id === "weak_form_constitutionalist") return "weak_form";

    // A remedial theory becomes the context focus only after the broader
    // constitutional/source/method/authority theories above have had a chance
    // to explain the respondent.
    if (has(t,"remedies.equilibration",0.5)) return "remedial_equilibration";
    if (has(t,"remedies.constitutional_common_law",0.5)) return "constitutional_common_law";
    if (has(t,"remedies.universal_relief_theory",0.5) && axis(scores,"remed") <= 38) return "universal_relief";
    if (has(t,"remedies.traditional_equity",0.5) && axis(scores,"remed") >= 62) return "traditional_equity";
    if (has(t,"remedies.structural",0.8) && has(t,"remedies.supervision",0.6) && axis(scores,"remed") <= 24) return "structural_reform";

    // Structure / form.
    if (id === "formalist") {
      if (has(t,"separation.strong_nondelegation",0.5)) return "formalist_nondelegation";
      if (has(t,"separation.unitary_executive",0.5)) return "formalist_unitary";
      if (has(t,"form.anti_discretion",0.65) || has(t,"form.rules",0.78)) return "formalist_rules";
      return "formalist_mainstream";
    }
    if (id === "functionalist") {
      if (has(t,"separation.supervisory_duty",0.5)) return "functionalist_supervisory";
      if (has(t,"separation.administrative_adjudication",0.5)) return "functionalist_admin";
      return "functionalist_mainstream";
    }
    if (id === "proportionalist" || id === "alexyan") {
      if (axis(scores,"sorc") <= 35 || has(t,"source.principles_are_law",0.5)) return "proportionalist_nonpositive";
      return "proportionalist_mainstream";
    }

    return "low_theory";
  }

  function fromId(id) {
    const route = ROUTES[id] || ROUTES.low_theory;
    return { id: ROUTES[id] ? id : "low_theory", opening: route.opening, context: route.context };
  }

  function build(classification, scores = {}, explicitId = null) {
    const id = explicitId && ROUTES[explicitId] ? explicitId : selectContextId(classification, scores);
    const route = ROUTES[id] || ROUTES.low_theory;
    return {
      id: ROUTES[id] ? id : "low_theory",
      opening: buildOpening(classification, scores),
      context: route.context
    };
  }

  function wordCount(text) {
    return String(text || "").trim().split(/\s+/).filter(Boolean).length;
  }

  global.LAW_RESULT_NARRATIVE = Object.freeze({
    ROUTES,
    OPENINGS,
    selectOpeningId,
    buildOpening,
    selectContextId,
    fromId,
    build,
    wordCount
  });
})(globalThis);
